INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:51','mayalex_normativos','09_JUDICIAL','Las Cortes de Apelaciones se compondrán de tres Magistrados cada una, y serán regidas por un Presidente, que será uno de los miembros propietarios.

Las funciones del Presidente durarán un año, contado desde el primero de enero, y serán desempeñadas por los miembros del Tribunal, turnándose por orden de antigüedad.

Los Magistrados tienen el rango y precedencia correspondientes a su antigüedad en el servicio del Tribunal.','51','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":51,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d458e3abc37834dcc2936a54cbf11f311e1ecb4f015676a88bf4f7d5e6faa3c8","ubicacion":[],"constancias":[{"nota":23,"tipo":"REFORMA","texto":"Reformado por Decreto Número 29, de fecha 24 de diciembre de 1937, publicado en el Diario Oficial La Gaceta número 10,388, del 30 de diciembre de 1937 y vigente a los 10 días de su promulgación. cuyo texto íntegro aparece al final, como anexo.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','51','d458e3abc37834dcc2936a54cbf11f311e1ecb4f015676a88bf4f7d5e6faa3c8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:52','mayalex_normativos','09_JUDICIAL','Para ser Magistrado de la Corte de Apelaciones se requiere:

1. Ser ciudadano en ejercicio de sus derechos.

2. Ser mayor de veinticinco años.

3. Tener título de Abogado.','52','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":52,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4942ffbd644a75606c14cca0d66a47c0cd60941c04e319450dca2e05798cbee8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','52','4942ffbd644a75606c14cca0d66a47c0cd60941c04e319450dca2e05798cbee8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:53','mayalex_normativos','09_JUDICIAL','No podrán ser Magistrados de las Cortes de Apelaciones los que no puedan ser Jueces de Letras.','53','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":53,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2ccb853b3266f62749bffd9d397531a672565bda9e81b35bc83425d810bae51d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','53','2ccb853b3266f62749bffd9d397531a672565bda9e81b35bc83425d810bae51d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:54','mayalex_normativos','09_JUDICIAL','Tampoco podrán ser simultáneamente Magistrados en una misma Corte de Apelaciones, los parientes dentro del cuarto grado de consanguinidad o segundo de afinidad.','54','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":54,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2e00168348b02c7e900b15f00b4a4af5cd709bd98fd17f0c0bd0c624b1087528","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','54','2e00168348b02c7e900b15f00b4a4af5cd709bd98fd17f0c0bd0c624b1087528','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:55','mayalex_normativos','09_JUDICIAL','Las Cortes de Apelaciones conocerán:

1. En primera instancia, de las demandas y acusaciones contra los Jueces de Letras para hacer efectiva civil o criminalmente su responsabilidad oficial.

2. En segunda instancia, de los asuntos civiles o criminales de que conocieren en primera los Jueces de letras, los árbitros de derecho y los Jueces de primera instancia militares.','55','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":55,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ab4c428ccdde8db584ae3548bfc94134edbd04a5a4a7b0d1356af520f45ff18d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','55','ab4c428ccdde8db584ae3548bfc94134edbd04a5a4a7b0d1356af520f45ff18d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:56','mayalex_normativos','09_JUDICIAL','Son aplicables a las Cortes de Apelaciones, para el castigo de las faltas de obediencia y respeto, las disposiciones del Artículo 42, pudiendo extender la multa hasta veinte pesos y el arresto hasta días.','56','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":56,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4e154c29fcfca7ba1745dc38960259dbf12ecdab4cfec73c578ee929b3896c21","ubicacion":[],"constancias":[{"nota":24,"tipo":"REFERENCIA","texto":"La Unidad monetaria actual de Honduras es el Lempira, según Decreto Número 102 de fecha 3 de abril de 1926.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','56','4e154c29fcfca7ba1745dc38960259dbf12ecdab4cfec73c578ee929b3896c21','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:57','mayalex_normativos','09_JUDICIAL','Las Cortes de Apelaciones conocerán de las quejas contra los Jueces de letras, por faltas en el ejercicio de sus funciones, en los mismos términos del Artículo 43, pudiendo extender la multa hasta veinte pesos.','57','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":57,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4a9fcbbe3496a3a886fb3ae02a65fab0c0963afd1c8e9386e1a15d0535cdb3c9","ubicacion":[],"constancias":[{"nota":25,"tipo":"REFERENCIA","texto":"Ver nota de pie anterior.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','57','4a9fcbbe3496a3a886fb3ae02a65fab0c0963afd1c8e9386e1a15d0535cdb3c9','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:58','mayalex_normativos','09_JUDICIAL','A las Cortes de Apelaciones corresponde inmediatamente mantener la disciplina judicial en su despacho y en la demarcación sujeta a su autoridad, y la observancia de todas las leyes relativas a la administración de justicia.

Podrán, al efecto, imponer las penas de amonestación verbal, censura por escrito o multa que no exceda de veinte pesos.','58','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":58,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"e56589aecf13cde0132f4f745b9caa15b8e057b314a279d494810e5a5d43389d","ubicacion":[],"constancias":[{"nota":26,"tipo":"REFERENCIA","texto":"Ver nota a pie de página anterior número 19.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','58','e56589aecf13cde0132f4f745b9caa15b8e057b314a279d494810e5a5d43389d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:59','mayalex_normativos','09_JUDICIAL','Las Cortes de Apelaciones, por medio de uno de sus Magistrados, siempre que lo estimen conveniente y de acuerdo con la Corte Suprema, o cuando ésta lo ordenare, visitarán los Juzgados de Letras de su jurisdicción.

El Magistrado visitador tendrá las mismas facultades disciplinarias que la Corte de Apelaciones para procurar la más pronta y cumplida administración de Justicia.','59','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":59,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"1ac968ccea5bec6a01d868500db989111bd7d9ebcca626bc2efbe1aa66f85c0e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','59','1ac968ccea5bec6a01d868500db989111bd7d9ebcca626bc2efbe1aa66f85c0e','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:60','mayalex_normativos','09_JUDICIAL','Las medidas que dictare el visitador se ejecutarán desde luego; pero podrán ser enmendadas o revocadas por la Corte de Apelaciones, en vista del informe del Magistrado y de las actas de visita.

De estos documentos y de las resoluciones que motivaren se dará cuenta a la Corte Suprema.','60','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":60,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b48a1d34c324ec5d1c6c4ed36ac9bf2c8cfd97bd50c5a6f7ba6168539bee3003","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','60','b48a1d34c324ec5d1c6c4ed36ac9bf2c8cfd97bd50c5a6f7ba6168539bee3003','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:61','mayalex_normativos','09_JUDICIAL','Para que una Corte de Apelaciones pueda ejercer las funciones que le corresponden, se requiere la concurrencia de todos sus Magistrados.','61','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":61,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"12dbdfb3b0f9a95ebc4596a82bdd3b3276c6d094492596a25558cd5e82462dd9","ubicacion":["CAPÍTULO II","DE LOS ACUERDOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','61','12dbdfb3b0f9a95ebc4596a82bdd3b3276c6d094492596a25558cd5e82462dd9','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:62','mayalex_normativos','09_JUDICIAL','Para dictar las providencias de mera tramitación de los procesos, bastará un solo Magistrado.

Se entenderán por providencias de mera tramitación las que recaigan sobre apersonamientos, rebeldías, peticiones de términos, apremios, unión de probanzas, señalamiento de vistas y su suspensión, y cualesquiera otras que tengan por objeto dar curso progresivo a los autos sin decidir ni prejuzgar ninguna cuestión debatida entre partes.

Pero toda reposición que se solicite de dichas providencias se resolverá en Tribunal pleno.','62','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":62,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"36d603fc93f658eb91f813fbab49ec9a03faf55a4bbe802799834da86f7e22f0","ubicacion":[],"constancias":[{"nota":27,"tipo":"REFERENCIA","texto":"Artículo 62. Véase Artículo 82 párrafo segundo del código de Procedimientos. Se exceptúan de esta disposición los escritos que tengan por objeto personarse en el juicio, acusar rebeldías, pedir apremios, prórroga de términos, unión de pruebas, señalamiento de vistas, su suspensión y cualesquiera otras diligencias de mera tramitación.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','62','36d603fc93f658eb91f813fbab49ec9a03faf55a4bbe802799834da86f7e22f0','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:63','mayalex_normativos','09_JUDICIAL','Todo acuerdo de una Corte de Apelaciones se constituye por los votos conformes de la mayoría absoluta.','63','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":63,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6920b6d7689125e4f086a4262cbcf300d75e99b9cc49540ffe91e7ce4cc42ba6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','63','6920b6d7689125e4f086a4262cbcf300d75e99b9cc49540ffe91e7ce4cc42ba6','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:64','mayalex_normativos','09_JUDICIAL','No podrán tomar parte en ningún acuerdo de las Cortes de Apelaciones, los Jueces que no hubieren concurrido como Magistrados a la vista del negocio.','64','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":64,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5609e061faece3773cc0a2521abdcc1b8ebbe3a7a0aad6ea5e402aee98299892","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','64','5609e061faece3773cc0a2521abdcc1b8ebbe3a7a0aad6ea5e402aee98299892','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:65','mayalex_normativos','09_JUDICIAL','Tampoco dejará de intervenir en el acuerdo ninguno de los Magistrados que hubiere concurrido a la vista del negocio, salvo los casos de los artículos siguientes.','65','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":65,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"1136cb553e827226caa927ac0b519f89baffa7680da4ec26c8f82dac20933123","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','65','1136cb553e827226caa927ac0b519f89baffa7680da4ec26c8f82dac20933123','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:66','mayalex_normativos','09_JUDICIAL','Si antes del acuerdo fuere removido de su empleo, o suspendido en el ejercicio de sus funciones alguno de los Magistrados que concurrieron a la vista, o si se le hubiere admitido la renuncia, se procederá a ver de nuevo el negocio como si no hubiere sido visto anteriormente.','66','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":66,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d7e766af015b304cfff1ee573809d1bdc166bb67871fc016278e98b3e43bb3f1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','66','d7e766af015b304cfff1ee573809d1bdc166bb67871fc016278e98b3e43bb3f1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:67','mayalex_normativos','09_JUDICIAL','Si antes del acuerdo se imposibilitase por enfermedad suya o de su familia, o por cualquier otra causa distinta de las apuntadas en el artículo anterior alguno de los Magistrados que concurrieron a la vista, se esperará hasta por diez días su asistencia al Tribunal, y si transcurrido ese término no pudiere asistir, se verá de nuevo el negocio.','67','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":67,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"3af481ff713424020b01662c947c58feea6ed207e42bc08399cb80a319c7d94c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','67','3af481ff713424020b01662c947c58feea6ed207e42bc08399cb80a319c7d94c','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:68','mayalex_normativos','09_JUDICIAL','Los Magistrados separados de su destino por licencia hasta de diez días quedarán obligados a concurrir al acuerdo.','68','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":68,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5b6443d5648b0bd8703a9f71bc221b1daf12a250357a1e65a373f429791d187f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','68','5b6443d5648b0bd8703a9f71bc221b1daf12a250357a1e65a373f429791d187f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:69','mayalex_normativos','09_JUDICIAL','En las sentencias definitivas o interlocutorias que pronunciaren las Cortes de Apelaciones se expresará nominalmente el Magistrado que hiciere voto particular.

En los procesos y en el libro copiador de sentencias se consignarán los votos particulares, debiendo publicarse éstos y aquéllas en el periódico de los Tribunales.','69','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":69,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f5fb3043f7e29fc400e1f7e7d1f64faf824ae38e02f3a22191feff4ce63cec59","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','69','f5fb3043f7e29fc400e1f7e7d1f64faf824ae38e02f3a22191feff4ce63cec59','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:70','mayalex_normativos','09_JUDICIAL','En los acuerdos los votos se darán en orden inverso al de la precedencia: el último voto será el del Presidente.','70','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":70,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"18605d376135ca13d65a83bb9adf35e162cc8f90f088e6ffa6f0aea8d2d54a29","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','70','18605d376135ca13d65a83bb9adf35e162cc8f90f088e6ffa6f0aea8d2d54a29','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:71','mayalex_normativos','09_JUDICIAL','A iniciativa de cualquier Magistrado, y para el mejor estudio del negocio, el Presidente diferirá la votación hasta por tres días.','71','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":71,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"cfd66267a63cf8691b39cd55a8d05a7fafbce1a13be826f680373e4fce9551b2","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','71','cfd66267a63cf8691b39cd55a8d05a7fafbce1a13be826f680373e4fce9551b2','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:72','mayalex_normativos','09_JUDICIAL','A los Presidentes de las Cortes de Apelaciones, fuera de las atribuciones que por otros artículos de esta ley se les confieren, les corresponden las siguientes:

1. Presidir o representar al Tribunal en todos los actos oficiales o en público.

2. Abrir y cerrar las sesiones del Tribunal, anticipar o prorrogar las horas del despacho cuando así lo requiera algún asunto urgente y grave, y convocar extraordinariamente al Tribunal cuando fuere necesario.

3. Dar las órdenes convenientes para integrar el Tribunal, cuando por impedimento, por licencia, o por cualquier otro motivo faltare el número de Magistrados necesario.

4. Determinar el orden en que deban verse los asuntos sujetos al conocimiento del Tribunal, guardando la regla indicada en el Artículo 110 de esta ley.

5. Mantener el orden dentro del Tribunal, amonestando a cualquier persona que lo perturbe, y aun haciéndola salir del local en caso necesario.

6. Dirigir los debates del Tribunal, concediendo la palabra a los Magistrados en el orden en que la pidieren.

7. Fijar las cuestiones que hayan de debatirse y las proposiciones sobre las cuales haya de recaer la votación.

8. Poner a votación las materias discutidas cuando el Tribunal haya declarado concluido el debate, con arreglo a lo dispuesto por el Código de Procedimientos.

9. Autorizar con su firma y la del Secretario las actas y acuerdos del Tribunal, y las comunicaciones con los Juzgados y Tribunales.

Las resoluciones que el Presidente dictare en uso de las atribuciones que se le confieren en este artículo, no podrán, en caso alguno, prevalecer contra el voto del Tribunal.','72','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":72,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5ea9820671a420f30165e10d3dbfeb1db18800556f800dca9f3f7c5eede57593","ubicacion":["CAPÍTULO III","DE LOS PRESIDENTES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','72','5ea9820671a420f30165e10d3dbfeb1db18800556f800dca9f3f7c5eede57593','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:73','mayalex_normativos','09_JUDICIAL','En ausencia del Presidente de una Corte de Apelaciones, hará sus veces el Magistrado más antiguo de los que se encontraren actualmente en el Tribunal.','73','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":73,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"be2f7b20de3bc3e7aa4d483c23356716c8e9c23c943cd0ddcfabfedf4d1892b9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','73','be2f7b20de3bc3e7aa4d483c23356716c8e9c23c943cd0ddcfabfedf4d1892b9','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:74','mayalex_normativos','09_JUDICIAL','La Corte Suprema de Justicia tendrá su asiento en la capital, y su jurisdicción comprenderá toda la República.','74','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":74,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a17dfb911a99b12f514b771285b36b75cca3d2ff7198d5704aaf51d67083f294","ubicacion":["TITULO V","DE LA CORTE SUPREMA"],"constancias":[{"nota":28,"tipo":"REFORMA_TACITA","texto":"Artículo 74 y 75. Reformado Tácitamente por Artículo 308 de la Constitución de la República de 1982 y sus reformas. La Corte Suprema de Justicia es le máximo órgano jurisdiccional; su jurisdicción comprende todo el territorio del estado y tiene su asiento en la capital, pero podrá cambiarlo temporalmente, cuando así lo determine, a cualquier otra parte del territorio. La Corte Suprema de Justicia estará integrada por quince (15) Magistrados. Sus","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"REFORMA_TACITA: la edición anota una reforma tácita que el texto no incorpora; CONTEXT hasta dictamen del CLO (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','74','a17dfb911a99b12f514b771285b36b75cca3d2ff7198d5704aaf51d67083f294','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:75','mayalex_normativos','09_JUDICIAL','La Corte Suprema se compondrá de quince Magistrados Propietarios, uno de los cuales será su Presidente.- La designación del Presidente se sujetará a lo dispuesto en el Artículo 315 de la Constitución de la República.','75','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":75,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"3b36042b8dafb8c387109e3326be75b4f92723509b431a887a5780723d884aad","ubicacion":[],"constancias":[{"nota":28,"tipo":"REFORMA_TACITA","texto":"Artículo 74 y 75. Reformado Tácitamente por Artículo 308 de la Constitución de la República de 1982 y sus reformas. La Corte Suprema de Justicia es le máximo órgano jurisdiccional; su jurisdicción comprende todo el territorio del estado y tiene su asiento en la capital, pero podrá cambiarlo temporalmente, cuando así lo determine, a cualquier otra parte del territorio. La Corte Suprema de Justicia estará integrada por quince (15) Magistrados. Sus","decretos":[]},{"nota":29,"tipo":"REFORMA","texto":"Artículo 75 Reformado por Artículo 315 de la Constitución de la República 1982 La Corte Suprema de Justicia cumplirá sus funciones constitucionales y legales bajo la presidencia de uno de sus magistrados. Para la elección del Presidente de la Corte, los Magistrados electos por el Congreso Nacional reunidos en pleno, seleccionará a más tardar veinticuatro (24) horas después de su elección y por el voto favorable de (2/3) dos terceras partes de sus miembros, al magistrado cuyo nombre será propuesto al congreso de la República para su elección como tal. Esta elección se efectuará de igual manera con el voto de dos terceras (2/3) partes de la totalidad de los miembros del congreso Nacional. El Presidente de la Corte Suprema de Justicia durará en sus funciones por un período de siete (7) años y podrá ser reelecto. El Presidente de la Corte Suprema de Justicia, ejercerá la representación del poder judicial y en ese carácter actuará de acuerdo con las decisiones adoptadas por la Corte en pleno.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"REFORMA_TACITA: la edición anota una reforma tácita que el texto no incorpora; CONTEXT hasta dictamen del CLO (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','75','3b36042b8dafb8c387109e3326be75b4f92723509b431a887a5780723d884aad','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:76','mayalex_normativos','09_JUDICIAL','La Corte Suprema tendrá tres Magistrados Suplentes.- Su período constitucional será de seis años, a contar del primero de enero más próximo a la fecha que tomaren posesión.','76','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":76,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b20195c75a15e27491480708b7cbb4dff23959c8fb7ce4ff35ac7460628c9937","ubicacion":[],"constancias":[{"nota":30,"tipo":"REFORMA","texto":"Artículo 76. De acuerdo a las reformas del poder Judicial ésta solamente establece magistrados propietarios. La Corte Suprema en lo referente a los Magistrados Suplentes y de conformidad con el Reglamento Interior, a fin de mantener el número requerido dentro de las Salas y del Pleno, en su artículo 15 letra d) dice: Hacer el llamamiento pertinente para integrar el Tribunal, cuando por impedimento, licencia o cualquier otro motivo, faltare alguna magistrado o Magistrado. Véase el artículo 104 de esta misma ley, que se refiere también a los magistrados suplentes.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','76','b20195c75a15e27491480708b7cbb4dff23959c8fb7ce4ff35ac7460628c9937','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:77','mayalex_normativos','09_JUDICIAL','Para ser Magistrado de la Corte Suprema se requieren las cualidades prescritas para los Magistrados de las Cortes de Apelaciones.- No podrán ser Magistrados de la Corte Suprema los que no puedan serlo de las Cortes de Apelaciones.

decisiones se tomarán por la mayoría de la totalidad de sus miembros.','77','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":77,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4aaf6316b00c0e524fa5d3d41b25c88de0ab57db884c4185a863535d58bc2df8","ubicacion":[],"constancias":[{"nota":31,"tipo":"REFORMA","texto":"Artículo 77. Reformado por Artículo 309 de la Constitución de la República 1982. Para ser Magistrado de la Corte Suprema de Justicia, se requiere: 1) Ser hondureño por nacimiento; 2) Ciudadano en el goce y ejercicio de sus derechos; 3) Abogado debidamente colegiado; 4) Mayor de treinta y cinco (35)años; 5) Haber sido titular de un órgano jurisdiccional durante cinco (5) años, o ejercido la profesión durante diez (10) años.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','77','4aaf6316b00c0e524fa5d3d41b25c88de0ab57db884c4185a863535d58bc2df8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:78','mayalex_normativos','09_JUDICIAL','La Corte Suprema, además de las atribuciones que las leyes le confieren, ejercerá las siguientes:

1. Hacer el Reglamento para su régimen interior.

2. Conocer de los delitos oficiales y comunes de los altos funcionarios del Estado, cuando el Congreso los haya declarado con lugar a formación de causa.

3. Autorizar a los Abogados, Notarios y Procuradores recibidos dentro o fuera de la República, para el ejercicio de su profesión, salvo lo estipulado en los tratados, y suspenderlos con arreglo a la ley.

4. Declarar que hay lugar a formación de causa, por delitos oficiales, contra los Miembros del Tribunal Superior de Cuentas, Fiscal General de Hacienda, Directores de Rentas, Correos y Comunicaciones Eléctricas, Gobernadores Políticos, Administradores de Rentas y Aduanas, Comandantes Departamentales, Secciónales o de Puertos, Directores Generales de Sanidad, Aeronáutica, de Turismo, Impuesto sobre la Renta, Trabajo, Agricultura y Obras Públicas, Caminos y de Censos y Estadísticas.

5. Conocer de los recursos de amparo y de revisión con arreglo a la ley.

6. Nombrar los Magistrados de las Cortes de Apelaciones, los Jueces de Letras departamentales y secciónales, y los representantes del Ministerio Público.

7. Conceder licencia a sus propios miembros y a los funcionarios o empleados de su nombramiento, y conocer de las renuncias de estos últimos.

8. Conocer de las causas de presas, de extradición y demás que deban juzgarse conforme al Derecho Internacional.

9. Conceder el pase a los suplicatorios, y declarar la autenticidad de los documentos judiciales y notariales que vengan del exterior para tener efecto en la República, y viceversa.

10. Suspender disciplinariamente y destituir a los funcionarios de su nombramiento por mala conducta o por faltas graves en el ejercicio de sus funciones, mediante información sumaria y audiencia del funcionario a quien se trate de suspender o destituir.','78','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":78,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6b0eb2848ad3da1ba5431e5400d879a85900a0bffd7221b25ace6bd849fb5d55","ubicacion":[],"constancias":[{"nota":32,"tipo":"REFORMA","texto":"Artículo 78 numeral 2). Reforma a la constitución de la república de 1982, Artículo 313 Numeral 2) por decreto No. 175-2003, pendiente de Ratificar en el año 2004: 2) Conocer de los procesos incoados a los altos funcionarios del Estado y Diputados.","decretos":["175-2003"]},{"nota":33,"tipo":"REFORMA","texto":"Numeral 1. Copiado en los términos del Decreto Número 24, de fecha 30 de enero de 1918, publicado en el Diario Oficial La Gaceta número 4921, del 9 de marzo de 1918, cuyo texto íntegro aparece al final, como anexo. 2. Artículo 78 numeral 3). La Corte Suprema de Justicia no expide el Titulo de Abogado sino las Universidades nacionales o extranjeras sean estas Públicas o privadas. La Corte expide El Exequátur del Notario según reforma a la Ley de Notariado por Decreto 277-2002 de fecha 8 de agosto del 2002. Y la Procuración el Colegio de Abogados de Honduras según el Reglamento vigente en dicha materia.","decretos":["277-2002"]},{"nota":34,"tipo":"REFORMA","texto":"Numeral 1. Copiado en los términos del Decreto Número 90, de fecha 7 de marzo de 1951, publicado en el Diario Oficial La Gaceta número 14,358, del 28 de marzo de 1951, cuyo texto íntegro aparece al final, como anexo. 2. Referente al Artículo 78 numeral 4). Los cargos señalados han variado o han sido suprimidos desde 1906 al 2004, por reformas a la Constitución de la República, ley de Administración Pública, la creación de otras instituciones Públicas Descentralizadas, Centralizadas y Autónomas entre otras, y en las cuales dichos funcionarios prestan promesas de Ley. El Artículo 205 Numeral 15 la Constitución de la República 1982 vigente establece que funcionario","decretos":[]},{"nota":35,"tipo":"REFORMA","texto":"Artículo 78 numeral 5). Reforma a la Constitución de la República de 1982. 5) Conocer de los recursos de casación, amparo, revisión e inconstitucionalidad de conformidad con esta Constitución y la Ley,","decretos":[]},{"nota":36,"tipo":"REFORMA","texto":"Artículo 78 numeral 6). Reforma a la Constitución de la República de 1982 8) Nombrar y remover los Magistrados y Jueces previa propuesta del Consejo de la Carrera Judicial. Los representantes del Ministerio Público son nombrados a partir de su creación en 1993 y de su vigencia el 6 de enero de 1994 la Ley del Ministerio Público por éste.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','78','6b0eb2848ad3da1ba5431e5400d879a85900a0bffd7221b25ace6bd849fb5d55','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:79','mayalex_normativos','09_JUDICIAL','Incumbe a la Corte Suprema la iniciativa constitucional de las leyes en asuntos de su competencia, y dar su dictamen en el término que el Congreso le señalare sobre las leyes relativas a la administración de justicia.

quienes gozan de tal prerrogativa. En la actualidad el congreso Nacional tiene como atribución declarar que haya o no lugar a formación de causa. El decreto No. 175-2003 de fecha 13 de noviembre el 2003, deroga en la primera legislatura tal atribución. Además el mismo decreto reforma al Artículo 313 numeral 2) quedando redactado así:…2) Conocer de los procesos incoados a los altos funcionarios del Estado y Diputados… 3)… y, 14) como atribución de la Corte Suprema de Justicia.','79','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":79,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"27ed255a88f19468de80df3814dff7a82a3eb4af71e5faeb1eda2ead8af9b839","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','79','27ed255a88f19468de80df3814dff7a82a3eb4af71e5faeb1eda2ead8af9b839','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:80','mayalex_normativos','09_JUDICIAL','La Corte Suprema conocerá:

1) En única instancia, de los recursos de casación que se entablaren contra las sentencias pronunciadas por las Cortes de Apelaciones, por los arbitradores, de conformidad con el Código de Procedimientos, y por el Tribunal Superior de Cuentas.
2) En segunda instancia, de las causas que conocen en primera instancia las Cortes de Apelaciones, o un Magistrado de la Corte Suprema, con arreglo a lo dispuesto en los dos Artículos siguientes.','80','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":80,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8171ad1b49a489baad14bbe6568f44d4c4af96b6c3852cce32556c079ffa66e8","ubicacion":[],"constancias":[{"nota":37,"tipo":"DEROGACION_PARCIAL","texto":"Artículo 80. Numeral 1): El conocimiento del recurso de casación corresponde exclusivamente a la Corte Suprema de Justicia. De conformidad al código de Procedimientos los casos en que procede únicamente es contra las sentencias definitivas pronunciadas por las Cortes de Apelaciones y sobre las emitidas por los Tribunales de Sentencia según el Código Procesal Penal Vigente. Contra las sentencias pronunciadas por los arbitradores fue derogada por la “Ley de Conciliación y Arbitraje” Decreto No. 161-2000 de fecha 17 de octubre de 2000, publicado en el Diario Oficial La Gaceta No. 29,404 de fecha 14 de febrero del 2001. Dicha Ley en la actualidad, es la que tiene la competencia para conocer sobre cuestiones litigiosa entre amigables componedores. Respecto al Tribunal Superior de Cuentas actual, éste no dicta sentencias sino Resolución definitiva contra la cual cabe el recurso de reposición y pone fin a la vía administrativa y el afectado queda habilitado para acudir a la Jurisdicción de lo Contencioso Administrativo.","decretos":["161-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (derogación parcial anotada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','80','8171ad1b49a489baad14bbe6568f44d4c4af96b6c3852cce32556c079ffa66e8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:81','mayalex_normativos','09_JUDICIAL','De las acusaciones o demandas que se entablaren contra uno o más miembros de la Corte Suprema o de las Cortes de Apelaciones para hacer efectiva su responsabilidad criminal o civil, conocerá en primera instancia un Magistrado de la Corte Suprema electo por ella misma.

Esta disposición es aplicable al conocimiento de los delitos oficiales y comunes de los altos funcionarios del Estado.','81','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":81,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5a2b4872b6e92b9d0b41cf0f3822b357449531add4fb2e58a1f78e2aa4ae81e6","ubicacion":[],"constancias":[{"nota":38,"tipo":"REFERENCIA","texto":"Artículo 81. Las Acusaciones y demandas para deducir responsabilidades a los jueces y magistrados se encausaran de conformidad al CAPÍTULO IV Del Antejuicio para Deducir Responsabilidades Criminal, del Código Procesal Penal, Decreto 9-99 E del 19 de diciembre de 1999.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','81','5a2b4872b6e92b9d0b41cf0f3822b357449531add4fb2e58a1f78e2aa4ae81e6','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:82','mayalex_normativos','09_JUDICIAL','De las causas de presas, de extradición y demás que deban juzgarse con arreglo al Derecho Internacional, conocerá en primera instancia uno de los Magistrados de la Corte Suprema, electo en los términos del artículo anterior.','82','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":82,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0122e64ab2dfe2cf47f4f45b711289924a89bcdc24a5a0d1d63e01789d7a2d90","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','82','0122e64ab2dfe2cf47f4f45b711289924a89bcdc24a5a0d1d63e01789d7a2d90','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:83','mayalex_normativos','09_JUDICIAL','Para la mejor administración de justicia, la Corte Suprema podrá dictar autos acordados, que son disposiciones reglamentarias de carácter general, encaminadas al cumplimiento exacto de las disposiciones legales vigentes en materia de justicia.

Los autos acordados se expedirán de oficio o por consulta de los Juzgados y Tribunales, pudiendo oírse con voto ilustrativo a todos los Magistrados, Jueces y Fiscales residentes en la capital.

Los autos acordados son disciplinarios, pudiendo llevar como sanción correccional multa que no exceda de treinta pesos.','83','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":83,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a9e6598e9d73e27e7a8cf00546fa1c90498fa306cc933c79734adcda57a1b1b7","ubicacion":[],"constancias":[{"nota":39,"tipo":"REFERENCIA","texto":"La Unidad monetaria actual de Honduras es el Lempira, según Decreto Número 102 de fecha 3 d abril de 1926.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','83','a9e6598e9d73e27e7a8cf00546fa1c90498fa306cc933c79734adcda57a1b1b7','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:84','mayalex_normativos','09_JUDICIAL','La Corte Suprema tendrá, en su caso, las facultades que corresponden a las Cortes de Apelaciones por el Artículo 56, para corregir las faltas de obediencia y respeto, pudiendo extender la multa hasta treinta pesos, y el arresto hasta treinta días.','84','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":84,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"e6eac277649e7cf04d19a4337c8dac01c22716f65b235c8891ca7942d77dedda","ubicacion":[],"constancias":[{"nota":40,"tipo":"REFERENCIA","texto":"Ver nota a pie de página anterior.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','84','e6eac277649e7cf04d19a4337c8dac01c22716f65b235c8891ca7942d77dedda','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:85','mayalex_normativos','09_JUDICIAL','Corresponde a la Corte Suprema ejercer la jurisdicción correccional, disciplinaria y económica sobre todos los Tribunales y Juzgados de la República.

En virtud de esta atribución puede, siempre que lo juzgue conveniente, corregir por sí misma las faltas o abusos que cualesquiera Jueces o funcionarios judiciales cometieren en el desempeño de su ministerio, con arreglo a los Artículos 57 y 58, pudiendo extender la multa hasta treinta Lempiras.

Puede, asimismo, amonestar a cualesquiera Jueces o funcionarios judiciales, o censurar su conducta, cuando ejercieren de un modo abusivo las facultades discrecionales que esta Ley les confiere, o cuando faltaren a cualquiera de los deberes anexos a su ministerio, sin perjuicio de formarse el proceso correspondiente.

Puede, además, siempre que notare que algún Juez o funcionario judicial ha cometido un delito que no ha recibido castigo según la Ley, reconvenir al Juez o funcionario que lo haya dejado impune, a fin de que se le aplique la pena correspondiente.','85','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":85,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8d63deea04b5defd825fe130a0c91c8ce7721200e2be0d20a5f231ed9c6e61c5","ubicacion":[],"constancias":[{"nota":41,"tipo":"REFERENCIA","texto":"Artículo 85. La vigilancia Judicial que de conformidad con la ley corresponde a la Corte Suprema de Justicia, se realiza por medio de la Inspectoría general de tribunales, según el reglamento respectivo emitido el 22 de julio de 1995 y publicado en el Diario Oficial La gaceta No. 27,745 de fecha 31 de agosto de 1995.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','85','8d63deea04b5defd825fe130a0c91c8ce7721200e2be0d20a5f231ed9c6e61c5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:86','mayalex_normativos','09_JUDICIAL','La Corte Suprema, siempre que lo estimare conveniente y por medio de uno de sus miembros, visitará las Cortes de Apelaciones y los Juzgados de Letras.

El Magistrado visitador tendrá las mismas facultades disciplinarias que la Corte Suprema, de conformidad con el Artículo 58.','86','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":86,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5e8b7e0a246f9a6fe3955af885d85acfa55fbda31688d85a92b93fb7597de6ff","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','86','5e8b7e0a246f9a6fe3955af885d85acfa55fbda31688d85a92b93fb7597de6ff','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:87','mayalex_normativos','09_JUDICIAL','Son aplicables a la Corte Suprema las disposiciones de esta Ley relativas a los acuerdos de las Cortes de Apelaciones y a los Presidentes de las mismas.','87','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":87,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"3474707bbd70dcae267f4f8e7aa31fda58a35eca7c5d783253cd5882a286ef9b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','87','3474707bbd70dcae267f4f8e7aa31fda58a35eca7c5d783253cd5882a286ef9b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:88','mayalex_normativos','09_JUDICIAL','La Corte Suprema publicará la "Gaceta Judicial", que será el periódico de los Juzgados y Tribunales.','88','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":88,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d5c60c1080cb05195f14160e14dbb7c7a7406c3cd4c32a0559dda7e7e744b41e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','88','d5c60c1080cb05195f14160e14dbb7c7a7406c3cd4c32a0559dda7e7e744b41e','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:89','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados pueden ser nombrados o elegidos con calidad de propietarios o de suplentes, de conformidad con esta Ley. Los Jueces de Letras pueden también ser nombrados con calidad de interinos.

Es propietario, el que es nombrado para ocupar por el período legal una plaza vacante.

Es suplente, el que es nombrado por el período legal para que desempeñe una plaza que no ha vacado o que no puede ser servida por falta o impedimento del propietario.

Es interino, el que es nombrado para que sirva una plaza vacante, mientras se proceda a nombrar el propietario o el suplente','89','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":89,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"47670f3cc2dad2a9f5dbb096cc4a8cb2df1a8d8c0b967ef3673b995632bd0832","ubicacion":["TITULO VI","DEL NOMBRAMIENTO INSTALACIÓN Y","SUBROGACIÓN DE LOS JUECES","Y MAGISTRADOS","CAPÍTULO I","DEL NOMBRAMIENTO DE LOS JUECES","Y MAGISTRADOS"],"constancias":[{"nota":42,"tipo":"REFORMA","texto":"Artículos 89, 91 y 92 Se debe tener en consideración la Reforma a la Constitución de la República de 1982, Artículo 313 numeral 8): Nombrar y remover los Magistrados y Jueces previa propuesta del Consejo de la Carrera Judicial. Respecto al Período de duración de sus funciones, los Magistrados de la Corte Suprema de Justicia será de 7 años pudiendo ser reelegidos y los magistrados de la Corte de Apelaciones y Jueces de Letras el período es conforme al a Ley de la Carrera Judicial.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','89','47670f3cc2dad2a9f5dbb096cc4a8cb2df1a8d8c0b967ef3673b995632bd0832','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:90','mayalex_normativos','09_JUDICIAL','Nombrado el Juez o Magistrado para ocupar una plaza vacante, y no expresándose en su título con qué calidad es nombrado, se entenderá que lo es con la de propietario; y con la de suplente si la plaza no estuviere vacante.','90','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":90,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0f4bb6f27c6fbc3e7b5d5062d5055fa54e522dc879421270ada2a44456c19b7c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','90','0f4bb6f27c6fbc3e7b5d5062d5055fa54e522dc879421270ada2a44456c19b7c','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:91','mayalex_normativos','09_JUDICIAL','Los Magistrados de la Corte Suprema, los de las Cortes de Apelaciones y los Jueces de Letras durarán en sus funciones seis años, que se computarán con arreglo a lo dispuesto en el Artículo 76, pudiendo volver a ser nombrados indefinidamente.','91','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":91,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5e402fdf3a13831edab0de2ab0cfe9b027a08708621785d1130ea416d2343171","ubicacion":[],"constancias":[{"nota":42,"tipo":"REFORMA","texto":"Artículos 89, 91 y 92 Se debe tener en consideración la Reforma a la Constitución de la República de 1982, Artículo 313 numeral 8): Nombrar y remover los Magistrados y Jueces previa propuesta del Consejo de la Carrera Judicial. Respecto al Período de duración de sus funciones, los Magistrados de la Corte Suprema de Justicia será de 7 años pudiendo ser reelegidos y los magistrados de la Corte de Apelaciones y Jueces de Letras el período es conforme al a Ley de la Carrera Judicial.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','91','5e402fdf3a13831edab0de2ab0cfe9b027a08708621785d1130ea416d2343171','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:92','mayalex_normativos','09_JUDICIAL','La Corte Suprema nombrará libremente los Magistrados de las Cortes de Apelaciones y los Jueces de Letras.

Para facilitar estos nombramientos, las Cortes de Apelaciones remitirán a aquel Tribunal, el 31 de diciembre de cada año, una lista completa de los Abogados residentes en su respectiva sección; lista que se publicará en el periódico de los Tribunales.','92','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":92,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"1ea892d15b3c41136fd60ef4be95d577913d8d8f767886069ae363d7d5a45f6b","ubicacion":[],"constancias":[{"nota":42,"tipo":"REFORMA","texto":"Artículos 89, 91 y 92 Se debe tener en consideración la Reforma a la Constitución de la República de 1982, Artículo 313 numeral 8): Nombrar y remover los Magistrados y Jueces previa propuesta del Consejo de la Carrera Judicial. Respecto al Período de duración de sus funciones, los Magistrados de la Corte Suprema de Justicia será de 7 años pudiendo ser reelegidos y los magistrados de la Corte de Apelaciones y Jueces de Letras el período es conforme al a Ley de la Carrera Judicial.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','92','1ea892d15b3c41136fd60ef4be95d577913d8d8f767886069ae363d7d5a45f6b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:93','mayalex_normativos','09_JUDICIAL','Todo Juez o Magistrado, para quedar instalado en el ejercicio de su cargo, hará la promesa siguiente: PROMETO SER FIEL A LA REPUBLICA, CUMPLIR Y HACER CUMPLIR LA CONSTITUCIÓN Y LAS LEYES.

El Juez o Magistrado que estando obligado a tomar posesión de su cargo se negare a ello, será apremiado discrecionalmente con pena disciplinaria, sin perjuicio de procesársele criminalmente.','93','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":93,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ce662b4a3e75a22d71e09be38fe0906dea1ca93a107e2847426f88a658f65544","ubicacion":["CAPÍTULO II","DE LA INSTALACIÓN DE LOS JUECES","Y MAGISTRADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','93','ce662b4a3e75a22d71e09be38fe0906dea1ca93a107e2847426f88a658f65544','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:94','mayalex_normativos','09_JUDICIAL','Los Magistrados de la Corte Suprema prestarán la promesa ante el Presidente del mismo Tribunal.

Los de las Cortes de Apelaciones, ante el Presidente del respectivo Tribunal.

Ante el mismo funcionario la prestarán los Jueces de Letras.

Ante los Jueces de Letras la prestarán los Jueces de paz.','94','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":94,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d34da89be50b47cde7b418332c5b54bf76fc21b6477b3fab2602927c7f2b3720","ubicacion":[],"constancias":[{"nota":43,"tipo":"REFORMA","texto":"Artículo 94 párrafo primero y Artículo 96. La Reforma a la Constitución de la República de 1982, establece que es el Congreso Nacional el que tomará la promesa de Ley al Presidente de la Corte y demás Magistrados que la integran. Artículo 205 Numeral 9). Elegir para el período que corresponda y de la nómina de candidatos que le proponga la junta nominadora a que se refiere esta Constitución, los Magistrados de la Corte Suprema de Justicia. 10); 11)…, 12). Recibir la promesa constitucional al Presidente y vicepresidente de la República, declarados elegidos, y a los demás funcionarios que elija…","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','94','d34da89be50b47cde7b418332c5b54bf76fc21b6477b3fab2602927c7f2b3720','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:95','mayalex_normativos','09_JUDICIAL','En los lugares donde no haya Corte de Apelaciones, los Jueces de Letras prestarán la promesa de ley ante el Alcalde Municipal.

Donde no haya Jueces de Letras, los Jueces de Paz prestarán la promesa ante el respectivo Alcalde.

El Alcalde que hubiere recibido la promesa dará inmediatamente aviso al respectivo Juzgado o Tribunal, remitiéndole la copia del acta.','95','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":95,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ca4a0227bf46ff0f4fbdc99bdd864c07fc51d27ba6b21e1a91a2e842e78cd167","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','95','ca4a0227bf46ff0f4fbdc99bdd864c07fc51d27ba6b21e1a91a2e842e78cd167','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:96','mayalex_normativos','09_JUDICIAL','Los integrantes de la Corte Suprema y de las Cortes de Apelaciones, prestarán la promesa la primera vez que fueren llamados en el año.

Los Jueces de Letras y los Jueces de Paz, por ministerio de la ley, no necesitarán prestarla.','96','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":96,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"10ef648000c9c3bef102441ed354dc86fc2de76d9b319a909a08c2856d48e6c4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','96','10ef648000c9c3bef102441ed354dc86fc2de76d9b319a909a08c2856d48e6c4','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:97','mayalex_normativos','09_JUDICIAL','La promesa de los Magistrados y Jueces se hará constar en el libro respectivo, extendiéndoseles la certificación correspondiente, si la pidieren.','97','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":97,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"37d4ac54258b0578ca3c5ef05615e1a7aff99b32a0de92a3f905b374f6d9aef1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','97','37d4ac54258b0578ca3c5ef05615e1a7aff99b32a0de92a3f905b374f6d9aef1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:98','mayalex_normativos','09_JUDICIAL','Cuando por excusa o recusación no pudiere un Juez de Paz conocer de un asunto determinado, será reemplazado por otro Juez de Paz propietario, de lo Civil o de lo Criminal, si lo hubiere; y a falta o por impedimento de éste, por el suplente o suplentes, Alcalde, Regidores o Síndico de la Municipalidad, por su orden.','98','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":98,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"71bd9fe334cc6c6f61467a1e5e87ab1da25a91ac6f2d43a290735349e809bd9c","ubicacion":["CAPÍTULO III","DE LA SUBROGACIÓN DE LOS JUECES","Y MAGISTRADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','98','71bd9fe334cc6c6f61467a1e5e87ab1da25a91ac6f2d43a290735349e809bd9c','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:99','mayalex_normativos','09_JUDICIAL','En los demás casos en que faltare un Juez de Paz, entrará a reemplazarlo el respectivo suplente, o el Alcalde y demás funcionarios municipales, en los términos del artículo anterior.','99','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":99,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6b6ceb0918c02b538cbfe1344d2fd1de34cdc13da01d1e4d4f2ae3ec28cd31b9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','99','6b6ceb0918c02b538cbfe1344d2fd1de34cdc13da01d1e4d4f2ae3ec28cd31b9','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:100','mayalex_normativos','09_JUDICIAL','En todos los casos en que faltare o no pudiere conocer de determinados negocios el Juez de Letras, su falta será suplida por el otro Juez de Letras de lo Civil o de lo Criminal, si lo hubiere en el asiento del Juzgado.

Si en el asiento del Juzgado no hubiere más que un Juez de Letras, la falta de éste será suplida por el Juez o Jueces de Paz, propietarios o suplentes, o por el Alcalde, Regidores y Síndico de la residencia del Juez, por su orden.','100','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":100,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8fc684a496af3311aee50e93e79382252ca7992785d9f846daaa8ac5b3d10dd8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','100','8fc684a496af3311aee50e93e79382252ca7992785d9f846daaa8ac5b3d10dd8','OLA12_LOAT_2007_01',now())
