INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:101','mayalex_normativos','09_JUDICIAL','La Corte Suprema nombrará dos Magistrados suplentes, por el período legal, para cada una de las Cortes de Apelaciones.','101','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":101,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"660ab2909fedc864963a346ab41244450c40736c9354c6444a8bbc3cf2e045bb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','101','660ab2909fedc864963a346ab41244450c40736c9354c6444a8bbc3cf2e045bb','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:102','mayalex_normativos','09_JUDICIAL','Tanto en la Corte Suprema, como en las Cortes de Apelaciones, los Magistrados suplentes servirán por turno mensual.','102','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":102,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8c1d088d6ec67ecfb874f45237e81bd63585db5e1b4883c4734ef858cfbcd321","ubicacion":[],"constancias":[{"nota":54,"tipo":"REFERENCIA","texto":"Artículo 1025. Código Civil. La información de que habla los dos (2) artículo precedentes, será remitida al Juez de Letras del último domicilio, si no lo fuere el que ha recibido la información; y el Juez, si encontrare que se han observado las solemnidades prescritas, y que en la información aparece claramente la última voluntad del testador, fallará que, según dicha información, el testador ha hecho las declaraciones y disposiciones siguientes, ( expresándolas); y mandará que valgan dichas declaraciones y disposiciones como testamento del difunto, y que se protocolice el expediente. No se mirarán como declaraciones y disposiciones testamentarias sino aquellas en que los testigos que asistieron por vía de solemnidad estuvieren conformes.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','102','8c1d088d6ec67ecfb874f45237e81bd63585db5e1b4883c4734ef858cfbcd321','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:103','mayalex_normativos','09_JUDICIAL','Si no pudiere entrar a desempeñar este cargo ninguno de los suplentes nombrados, se llamarán otro Abogados en calidad de integrantes, los cuales se designarán, en cada caso, por los Magistrados que quedaren del Tribunal, siempre que reúnan las condiciones para ser Magistrados.

El llamamiento de integrantes de que habla el párrafo precedente, se hará saber a las partes antes de entrar aquéllos en el ejercicio de sus funciones.

Si no hubiere Abogados, podrán llamarse como integrantes otras personas que reúnan las demás cualidades requeridas para ser Magistrados.','103','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":103,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"7ab531717663a4bb2e593bb2c1c865e48ebf725ebbc7f2bbe9c103d217959234","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','103','7ab531717663a4bb2e593bb2c1c865e48ebf725ebbc7f2bbe9c103d217959234','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:104','mayalex_normativos','09_JUDICIAL','Los suplentes e integrantes de la Corte Suprema y de las Cortes de Apelaciones, devengarán las dietas que la ley asigne a los Magistrados cuando presten su asistencia al Tribunal.

Esta disposición es aplicable a los Jueces de Letras por ministerio de la ley.','104','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":104,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4859c1549dd572514e9368c30a18b6d838079cd4260ede2f6e2f27725966c3fc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','104','4859c1549dd572514e9368c30a18b6d838079cd4260ede2f6e2f27725966c3fc','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:105','mayalex_normativos','09_JUDICIAL','Todos los Jueces y Magistrados propietarios están obligados a residir constantemente en la ciudad o población donde tenga su asiento el Juzgado o Tribunal en que deben prestar sus servicios, excepto cuando tengan que ausentarse por razón del servicio en los casos que determinen las leyes.

Los suplentes en su turno, y los integrantes en su caso, no podrán ausentarse sin autorización del Juzgado o Tribunal.','105','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":105,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"58a538466e098ccd34d9d0ff85a0282d2d41acbf2f7754e932cf2ec1c7db34f0","ubicacion":["TITULO VII","DE LOS DEBERES Y PROHIBICIONES","DE LOS JUECES Y MAGISTRADOS"],"constancias":[{"nota":44,"tipo":"REFERENCIA","texto":"El Artículo 45 de la Ley de la Carrera Judicial señala que \"Los funcionarios y empleados deben residir en la sede de su cargo, de la cual no podrán ausentarse en los días y horas de trabajó, sino con permiso. Empero, el respectivo superior podrá autorizar la residencia en lugar distinto de la sede por motivos justificados y siempre que no se perjudique la marcha del trabajo\".","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','105','58a538466e098ccd34d9d0ff85a0282d2d41acbf2f7754e932cf2ec1c7db34f0','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:106','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados propietarios, y los suplentes en su caso, están obligados a asistir a so oficina todos los días y a permanecer en ella desempeñando sus funciones durante tres horas antes y tres horas después del medio día por lo menos.','106','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":106,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8c4dfa3c9f8cf2ae8da8d96c85e3e198d7cf078425da9ad1dd9147caf750b63a","ubicacion":[],"constancias":[{"nota":45,"tipo":"REFORMA","texto":"Artículo 106. Reformado mediante Decreto No. 153 del 20 de marzo de 1935, publicado en el Diario Oficial La Gaceta No. 9,562 del tres de abril de 1935 y vigente 20 días después de su sanción. En la actualidad las funciones se desempeñan en jornada ordinaria. Los días feriados nacionales son: 1º de enero, 14 de abril, 1º de mayo, 15 de septiembre, 3 de octubre, 12 de octubre, 21 de octubre y 25 de diciembre, aunque caigan en domingo; el jueves, viernes y sábado de la Semana Santa. Pero de conformidad al Decreto No.162-99 del 20 de octubre de 1999 que reforma el Artículo 3 del Decreto No.288.98 de fecha 24 de diciembre de 1998, en el cual se declara, además de las contempladas en leyes especiales y en los contratos, como fiestas cívicas nacionales sin suspensión de labores, las siguientes fechas: 1) 14 de abril. Día de las Ameritas, 2) 17 de septiembre Día del Maestro; 3) 3 de octubre, nacimiento de francisco Morazán, Día del soldado; 4) 12 de octubre. Día de la Raza o descubrimiento de América; y 5) 21 de octubre. Día de las Fuerzas Armadas. La Corte Suprema de Justicia además de considerar los feriados arriba mencionados ha establecido dos períodos vacacionales en julio y diciembre de 15 días cada uno respectivamente. Dejando en tal período habilitado en el país, algunos juzgados en las diferentes materias","decretos":["153","162-99","288"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','106','8c4dfa3c9f8cf2ae8da8d96c85e3e198d7cf078425da9ad1dd9147caf750b63a','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:107','mayalex_normativos','09_JUDICIAL','Las obligaciones de residencia y asistencia diaria, cesarán durante los días feriados.

Son feriados únicamente los domingos, el primero de enero y el quince de septiembre.','107','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":107,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"33267f366d5e802a3e770ad5a330906963e0a73cd1a6a47c8a35595ad1b0c356","ubicacion":[],"constancias":[{"nota":46,"tipo":"REFERENCIA","texto":"El Artículo 1.- del Decreto número 96, de fecha 4 de marzo de 1949, publicado en el Diario Oficial La Gaceta número 13749 del 8 de marzo de 1949, cuyo texto íntegro aparece al final, como anexo, estableció: \"Para todos los efectos civiles, judiciales, administrativos y mercantiles, serán días inhábiles o feriados, todos los domingos del año, el 1 de enero, el 15 de marzo, el 14 de abril, el 14 de julio, el 15 de septiembre, el 12 de octubre, el 25 de diciembre y el jueves, viernes y sábado de la Semana Santa\". Por su parte, el Código del Trabajo, fijó a los patronos la obligación de pagar \"los siguientes días feriados o de fiesta nacional: 11 de enero, 14 de abril, 11 de mayo, 15 de septiembre, 3 de octubre, 12 de octubre, 21 de octubre y 25 de diciembre, aunque caigan en domingo, y el jueves, viernes y sábado de la Semana Santa\". La Ley de Procedimiento Administrativo en su Artículo 47, establece que \"se entenderán días hábiles","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','107','33267f366d5e802a3e770ad5a330906963e0a73cd1a6a47c8a35595ad1b0c356','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:108','mayalex_normativos','09_JUDICIAL','Es prohibido a todos los Jueces y Magistrados ejercer la abogacía, y la procuración en cualquier Juzgado o Tribunal, y sólo podrán defender causas personales, o de su cónyuge, pupilos y parientes dentro del cuarto grado de consanguinidad o segundo de afinidad.

La prohibición del párrafo anterior no comprende a los Jueces y Magistrados suplentes, ni a los Jueces de Paz.','108','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":108,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"9ed5cd9451b594cb511bec0d170df398b3d07a2af8817c900c91ae8902be3f90","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','108','9ed5cd9451b594cb511bec0d170df398b3d07a2af8817c900c91ae8902be3f90','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:109','mayalex_normativos','09_JUDICIAL','El ejercicio del notariado es prohibido a los Magistrados propietarios, pero no a los suplentes.','109','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":109,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"43cd948663c0e351608752baf8cad248a533de6426c7159830b8ea5c729d3062","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','109','43cd948663c0e351608752baf8cad248a533de6426c7159830b8ea5c729d3062','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:110','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados están obligados a despachar los asuntos sometidos a su conocimiento con toda la brevedad que las atenciones de su ministerio les permitan, guardando el orden de antigüedad de los asuntos, salvo cuando motivos graves y urgentes exijan que dicho orden se altere.','110','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":110,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f35da5620ae4551fe9f39a202411a189e4d3a8338d0f97b6d78b7e978840af13","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','110','f35da5620ae4551fe9f39a202411a189e4d3a8338d0f97b6d78b7e978840af13','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:111','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados deberán abstenerse, en absoluto, de expresar y aun de insinuar su juicio respecto de los asuntos que por ley son llamados a fallar.

Deberán, igualmente, abstenerse de dar oídos a toda alegación que las partes, o cualesquiera personas, a nombre de ellas, intentaren hacerles en cualesquiera lugares y circunstancias.','111','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":111,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2be207bb861c5de35b57544a639431d1b8b5fd78f19971ed3da057a59df20b31","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','111','2be207bb861c5de35b57544a639431d1b8b5fd78f19971ed3da057a59df20b31','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:112','mayalex_normativos','09_JUDICIAL','Es prohibido a todo los Jueces y Magistrados, bajo pena de nulidad, comprar o adquirir a cualquier titulo, para sí o para otro, las cosas o derechos que se administrativos, todos los del año, excepto los sábados en aquellas oficinas donde no se labore por disposición gubernamental, los domingos, feriados nacionales y los que mandare que vaquen las oficinas públicas. Son feriados nacionales el 11 de enero, 14 de abril, 11 de mayo, 15 de septiembre, 3 de octubre, 12 de octubre, 21 de octubre y 25 de diciembre y el jueves, viernes y sábado de la Semana Santa".

Finalmente el Decreto Número 91-95 de fecha 16 de mayo de 1995, por medio del cual se reforma el Artículo 91 del Código de Procedimientos Civiles, en parte señala: "Son días hábiles los no feriados. Son horas hábiles las que medien entre la salida y la puesta del sol. Tendrán la categoría de días inhábiles, para los efectos judiciales, los sábados, domingos y aquellos en que por acuerdo de la Corte Suprema de Justicia, el personal de sus dependencias administrativas, juzgados y tribunales de la República, gocen de vacaciones o asueto".

litiguen en los juicios de que conozcan.','112','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":112,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"67e76059b8164599bb770a3e8dccdda038a0a7dbe035dd748155846a801da3e8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','112','67e76059b8164599bb770a3e8dccdda038a0a7dbe035dd748155846a801da3e8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:113','mayalex_normativos','09_JUDICIAL','La Corte Suprema podrá conceder licencia a sus propios miembros, a los Magistrados de las Cortes de Apelaciones, a los Jueces de Letras, y a los demás empleados de su nombramiento, hasta por tres meses en el año.

Se concederá el goce de sueldo por un mes de licencia.

Las Cortes de Apelaciones podrán conceder licencia a los empleados de su nombramiento, en los mismos términos de los párrafos anteriores.

Igual facultad corresponde a los Jueces de Letras respecto de sus subalternos y de los Jueces de Paz, y a éstos, respecto de sus subalternos.','113','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":113,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2b10efd011333214215e6c71a9a39e808a5f67cf6fb807e9ecefae668b6cd75a","ubicacion":["TITULO VIII","DE LAS LICENCIAS Y DE LA SUSPENSIÓN","Y TERMINACIÓN DE LAS FUNCIONES","DE LOS JUECES Y MAGISTRADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','113','2b10efd011333214215e6c71a9a39e808a5f67cf6fb807e9ecefae668b6cd75a','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:114','mayalex_normativos','09_JUDICIAL','El cargo de los Jueces y Magistrados se suspenderá:

1. Por licencia.

2. Por hallarse procesados por delitos graves o por simples delitos, ya sean oficiales o comunes.

Se entiende que hay proceso en los delitos oficiales desde que se declara que hay lugar a formación de causa, o que es admisible la acusación, y en los delitos comunes desde que se decreta auto de prisión, o de declaratoria de reo.

El Juez o Magistrado que fuere absuelto volverá al ejercicio de su cargo.

3. Por sentencia ejecutoria que imponga la suspensión como pena principal.','114','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":114,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0f7ae1cb74e53aae9e3dac989adeda116fb3df0bb78f3c4c1d3b81bf3549f0e3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','114','0f7ae1cb74e53aae9e3dac989adeda116fb3df0bb78f3c4c1d3b81bf3549f0e3','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:115','mayalex_normativos','09_JUDICIAL','El cargo de los Jueces y Magistrados terminará:

1. Por renuncia del mismo cargo aceptada legalmente.

2. Por promoción a otro empleo judicial, si se aceptare el nuevo nombramiento.

3. Por la aceptación de un cargo del orden administrativo, si el cargo lleva anexa jurisdicción.

Se entiende por jurisdicción administrativa el poder o autoridad que tienen los empleados públicos, individual o colectivamente, para gobernar y poner en ejecución las leyes en el orden administrativo.

4. Por incurrir en la pena de inhabilitación absoluta o especial para el cargo.

5. Por sentencia firme que le imponga pena más que correccional.

6. Por incurrir en alguna incapacidad legal para ejercer el cargo.

Si dos miembros de un Tribunal contrajeren afinidad dentro del segundo grado, aquel por cuyo matrimonio se haya contraído el parentesco cesará en su destino.

7. Por concluir el período del nombramiento o elección.

Las funciones de los Jueces y Magistrados se prorrogarán de derecho hasta que tome posesión su sucesor, aunque tuvieren substituto legal.','115','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":115,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8dbf1e2c4e7858f287779a7f2c3f52ff8360fa74a389454eba66b788820852a3","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','115','8dbf1e2c4e7858f287779a7f2c3f52ff8360fa74a389454eba66b788820852a3','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:116','mayalex_normativos','09_JUDICIAL','Se llaman Árbitros los Jueces nombrados por las partes, de común acuerdo, o por la autoridad judicial en subsidio, para la resolución de un asunto litigioso.

Este nombramiento puede hacerse con calidad de Árbitros de derecho, o con la de Arbitradores o Amigables componedores.','116','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":116,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"e024af56ba790e05ef39e42ef33fdbd76f9a038c301ac727a7f04351ec75fe56","ubicacion":["TITULO IX","DE LOS JUECES ARBITROS"],"constancias":[{"nota":47,"tipo":"REFORMA_TACITA","texto":"Artículo 116. Párrafo segundo y Artículo119. Fueron Derogados Tácitamente por la “Ley de Conciliación y Arbitraje” Decreto No. 161-2000 de fecha 17 de octubre de 2000, publicado e el Diario Oficial la Gaceta No. 29,404 de fecha 14 de febrero del 2001. Esta ley es la que tiene competencia para conocer sobre cuestiones litigiosas entre amigables componedores.","decretos":["161-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"REFORMA_TACITA: la edición anota una reforma tácita que el texto no incorpora; CONTEXT hasta dictamen del CLO (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','116','e024af56ba790e05ef39e42ef33fdbd76f9a038c301ac727a7f04351ec75fe56','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:117','mayalex_normativos','09_JUDICIAL','Deberán resolverse por Árbitros:

1. La liquidación de una sociedad conyugal, o de una sociedad colectiva o en comandita civil.

2. La partición de bienes.

3. Las cuestiones a que diere lugar la presentación de la cuenta del gerente o del liquidador de una sociedad comercial.

4. Las diferencias que ocurrieren entre los socios de una sociedad anónima, o de una sociedad colectiva o en comandita comercial, o entre los asociados de una cuenta en participación.','117','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":117,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ff5173473623cebeb8d9eef80359a93ca5380412ded8c99be68e52832e572a2f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','117','ff5173473623cebeb8d9eef80359a93ca5380412ded8c99be68e52832e572a2f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:118','mayalex_normativos','09_JUDICIAL','No podrán resolverse por Árbitros:

1. Las causas criminales, en ningún caso.

2. Los asuntos civiles en que deba ser oído el Ministerio Público, sin perjuicio de lo dispuesto en el Artículo anterior.','118','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":118,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"959020bcb7f344893fccb4c47787d42cce37257b82740a4e29ab8feda02fc3e5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','118','959020bcb7f344893fccb4c47787d42cce37257b82740a4e29ab8feda02fc3e5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:119','mayalex_normativos','09_JUDICIAL','Del nombramiento de los Árbitros y de sus atribuciones se trata en el Código de Procedimientos.','119','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":119,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"c7bdf1b9c02431569051d7e0e244ed9e774d9bac2febc9da57cba93d7da233a1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','119','c7bdf1b9c02431569051d7e0e244ed9e774d9bac2febc9da57cba93d7da233a1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:120','mayalex_normativos','09_JUDICIAL','La responsabilidad criminal podrá exigirse a los Jueces y Magistrados cuando infringieren leyes relativas al ejercicio de sus funciones, en los casos expresamente previstos en el Código Penal o en otras leyes especiales.

Esta disposición sólo es aplicable a los Magistrados de la Cortes Suprema cuando sean declarados con lugar a formación de causa, de conformidad con el Artículo 139 de la Constitución.','120','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":120,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"98597a7fdefd3c746b3bffcfc1719d49e200517b5127292b3d4d14a81a69636f","ubicacion":["TITULO X","DE LA RESPONSABILIDAD JUDICIAL","CAPÍTULO I","DE LA RESPONSABILIDAD CRIMINAL","DE LOS JUECES Y MAGISTRADOS"],"constancias":[{"nota":48,"tipo":"REFERENCIA","texto":"Artículo 120. Las Acusaciones y demandas para deducir responsabilidad a los jueces y magistrados se encausaran de conformidad al CAPÍTULO IV, Del Antejuicio para Deducir Responsabilidad Criminal, del Código Procesal Penal, Decreto 9-99 E del 19 de diciembre de 1999. El artículo 139 corresponde a la Constitución de 1906.","decretos":["9-99"]},{"nota":49,"tipo":"REFERENCIA","texto":"De acuerdo con el Artículo 205, numeral 15, de la Constitución de la República, corresponde a Congreso Nacional hacer esta declaración.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','120','98597a7fdefd3c746b3bffcfc1719d49e200517b5127292b3d4d14a81a69636f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:121','mayalex_normativos','09_JUDICIAL','El juicio de responsabilidad criminal contra los Jueces y Magistrados sólo podrá incoarse:

1. En virtud de providencia de Juzgado o Tribunal competente.

2. A instancia del Ministerio Público.

3. A instancia de la parte agraviada o de sus causahabientes.','121','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":121,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8f284160ee353d8c54ec61ffbac67aaa1edd427c5becbf0c116bbee0938d7e4d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','121','8f284160ee353d8c54ec61ffbac67aaa1edd427c5becbf0c116bbee0938d7e4d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:122','mayalex_normativos','09_JUDICIAL','Cuándo la Corte Suprema, por razón de los pleitos o causas de que conozca, o de la inspección y vigilancia que sobre sus inferiores ejerza, o por cualquier otro medio, tuviere noticia de algún acto de Jueces o Magistrados que pueda calificarse de delito, mandará formar causa para su averiguación y castigo, oyendo, previamente, al Ministerio Público.','122','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":122,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"30f89ff4c1e7a09e1d3748739d3192dfc532f17837232fca02cd9b99f049bc52","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','122','30f89ff4c1e7a09e1d3748739d3192dfc532f17837232fca02cd9b99f049bc52','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:123','mayalex_normativos','09_JUDICIAL','Lo ordenado en el artículo anterior será extensivo a los demás Jueces y Tribunales, en el caso de que sea de su competencia conocer del hecho que pueda calificarse de delito.

Si no fuere de su competencia, pondrán en conocimiento del Juzgado, o Tribunal que la tenga, los hechos, con los antecedentes que puedan ser útiles en los autos.','123','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":123,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4534d74e61b23dcd52f953b37cec090a4eb94f8a9360ce1aaec90a4914222c35","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','123','4534d74e61b23dcd52f953b37cec090a4eb94f8a9360ce1aaec90a4914222c35','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:124','mayalex_normativos','09_JUDICIAL','El Juez o Tribunal competente pondrá en conocimiento de su Fiscal los hechos y los antecedentes que tenga, para que pueda ejercitar la acción criminal correspondiente.','124','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":124,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f2b4ea51ec71e8370ad0e36cb9b895d806740bba3ae55b043863f5d1a538a741","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','124','f2b4ea51ec71e8370ad0e36cb9b895d806740bba3ae55b043863f5d1a538a741','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:125','mayalex_normativos','09_JUDICIAL','El Ministerio Público podrá promover procedimientos criminales:

1. En cumplimiento de una orden de Juzgado o Tribunal competente.

2. En cumplimiento del deber que tiene de promover el descubrimiento y el castigo de los delitos.','125','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":125,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"74806fc92932c1b8a9ed51d486aa810160de7bd8b6b3f6a6fd9236bc8de10c07","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','125','74806fc92932c1b8a9ed51d486aa810160de7bd8b6b3f6a6fd9236bc8de10c07','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:126','mayalex_normativos','09_JUDICIAL','Cuando un Fiscal incompetente tuviere conocimiento de haber delinquido algún Juez o Magistrado, lo comunicará al Fiscal correspondiente.','126','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":126,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5dbac4d5deea80e83af9e517346616508ff031a02f4f6a9fabcbad21e394afa8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','126','5dbac4d5deea80e83af9e517346616508ff031a02f4f6a9fabcbad21e394afa8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:127','mayalex_normativos','09_JUDICIAL','Para que pueda incoarse causa para exigir la responsabilidad criminal a Jueces o Magistrados, deberá proceder un antejuicio con arreglo a los trámites que establece el Código de Procedimientos, que tendrá por objeto declarar la admisibilidad de la acusación.

Esta declaración no prejuzgará su criminalidad.','127','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":127,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"7bb0aef99bb22f40a7889790fea062e59b7e5c64e1327d87667785d78682c0fb","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','127','7bb0aef99bb22f40a7889790fea062e59b7e5c64e1327d87667785d78682c0fb','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:128','mayalex_normativos','09_JUDICIAL','Del antejuicio de que trata el Artículo que precede conocerá el mismo Juzgado o Tribunal que en su caso deba conocer de la causa.','128','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":128,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6713c489a62138c72177b1a6fec354b1b267c03e17ceed2c18e07d4b426cdea5","ubicacion":[],"constancias":[{"nota":50,"tipo":"REFERENCIA","texto":"Artículo 128. Las Acusaciones y demandas para deducir responsabilidad a los Jueces y Magistrados se encausaran de conformidad al CAPÍTULO IV, Del Antejuicio para Deducir Responsabilidad Criminal, del Código Procesal Penal, Decreto 9-99 E del 19 de diciembre de 1999.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','128','6713c489a62138c72177b1a6fec354b1b267c03e17ceed2c18e07d4b426cdea5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:129','mayalex_normativos','09_JUDICIAL','Fuera de los casos a que se refiere el Artículo 120, la responsabilidad civil de los Jueces y Magistrados estará limitada al resarcimiento de los daños y perjuicios estimables que causen a las partes, cuando en el desempeño de sus funciones infrinjan las leyes por negligencia o ignorancia inexcusables.','129','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":129,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0bbde49fdf917ea7737a09bfb6f5deefd40720d90e9b3bf6daa2a1c7b6ace1fd","ubicacion":["CAPÍTULO II","DE LA RESPONSABILIDAD CIVIL","DE LOS JUECES Y MAGISTRADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','129','0bbde49fdf917ea7737a09bfb6f5deefd40720d90e9b3bf6daa2a1c7b6ace1fd','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:130','mayalex_normativos','09_JUDICIAL','Se entenderá por perjuicios estimables, para los efectos del artículo anterior, todos los que pueden ser apreciados en metálico, al prudente arbitrio de los Juzgados o Tribunales.','130','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":130,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"10cbbddf0b68755ce768e1fc3f9674c031c740f48eab0cfff97e01905158432b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','130','10cbbddf0b68755ce768e1fc3f9674c031c740f48eab0cfff97e01905158432b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:131','mayalex_normativos','09_JUDICIAL','Se tendrán por inexcusables la negligencia o la ignorancia cuando, aunque sin intención, se hubiere dictado providencia manifiestamente contraria a la ley, o se hubiere faltado a algún trámite o solemnidad mandado observar por la misma ley bajo pena de nulidad.','131','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":131,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"81ad0abcb030addbfb928cdc5294deb860a47e56a872b8ef2624e63dc1dff575","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','131','81ad0abcb030addbfb928cdc5294deb860a47e56a872b8ef2624e63dc1dff575','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:132','mayalex_normativos','09_JUDICIAL','La responsabilidad civil solamente podrá exigirse a instancia de la parte perjudicada o de sus causahabientes, en juicio ordinario y ante el Juzgado o Tribunal inmediatamente superior al que hubiere incurrido en ella.','132','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":132,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"80b38e6356e6b811dc873e519eaf745d365fb0050ff6c118427090707c2f43b1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','132','80b38e6356e6b811dc873e519eaf745d365fb0050ff6c118427090707c2f43b1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:133','mayalex_normativos','09_JUDICIAL','No podrá entablar el juicio de responsabilidad civil el que no haya reclamado oportunamente durante el juicio, pudiendo hacerlo.','133','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":133,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"126faf3c956e0810ca01e07e1e1c268e54052fda8e280abc78c791a37cfadb6b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','133','126faf3c956e0810ca01e07e1e1c268e54052fda8e280abc78c791a37cfadb6b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:134','mayalex_normativos','09_JUDICIAL','La responsabilidad judicial afectará solidariamente a todos los Jueces y

Magistrados que hubieren incurrido en ella.','134','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":134,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ed28cbb28df32334a5d97727c5293569aebbf849ded9d34a7b1f88b9d166b430","ubicacion":["CAPÍTULO III","DISPOSICIONES COMUNES","A LOS DOS CAPÍTULOS ANTERIORES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','134','ed28cbb28df32334a5d97727c5293569aebbf849ded9d34a7b1f88b9d166b430','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:135','mayalex_normativos','09_JUDICIAL','Las acciones que establece este Título no podrán entablarse mientras estuviere pendiente la causa o pleito en que se supone el agravio, y prescribirán en un año, a contar desde que termine el asunto.','135','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":135,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0a04db49409d0ccf24db397fb1004b3e27a5cecebd9a95adb4018f12195c6756","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','135','0a04db49409d0ccf24db397fb1004b3e27a5cecebd9a95adb4018f12195c6756','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:136','mayalex_normativos','09_JUDICIAL','En ningún caso la sentencia pronunciada en el juicio de responsabilidad alterará la sentencia firme.','136','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":136,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2db9e28ef0288fa65302b2d598033e5f0b86165431ce5246c83560f915635b78","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','136','2db9e28ef0288fa65302b2d598033e5f0b86165431ce5246c83560f915635b78','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:137','mayalex_normativos','09_JUDICIAL','La competencia es la facultad que tiene cada Juez o Tribunal para conocer de los negocios que las leyes han colocado dentro de la esfera de sus atribuciones.','137','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":137,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"bae79a57be2f9f92d843f97dc409785bf07895ea3fbccf23b1312b6246b575d1","ubicacion":["TITULO XI","DE LA COMPETENCIA","CAPÍTULO I","DISPOSICIONES COMUNES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','137','bae79a57be2f9f92d843f97dc409785bf07895ea3fbccf23b1312b6246b575d1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:138','mayalex_normativos','09_JUDICIAL','Radicado con arreglo a la ley el conocimiento de un negocio ante el Juez o Tribunal competente, no se alterará esta competencia por causa sobreviniente.','138','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":138,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"161979135208bbef2349db8919f8df6fc2d87cc278c4f9c08b69d520603cab44","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','138','161979135208bbef2349db8919f8df6fc2d87cc278c4f9c08b69d520603cab44','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:139','mayalex_normativos','09_JUDICIAL','Una vez fijada con arreglo a la ley la competencia de un Juez o Tribunal inferior para conocer en primera instancia de un determinado asunto, queda igualmente fijada la del Juez o Tribunal superior que debe conocer del mismo asunto en segunda instancia.','139','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":139,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"9f7ecfaaa5706c23c6053c0e976795ce4674bdfdac48888a36fd33ba37365db7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','139','9f7ecfaaa5706c23c6053c0e976795ce4674bdfdac48888a36fd33ba37365db7','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:140','mayalex_normativos','09_JUDICIAL','Los Jueces y Tribunales que tengan competencia para conocer de un pleito o de causa determinada, la tendrán también para las excepciones que en ellos se propongan, para la reconvención en los casos en que proceda, para todas sus incidencias, para llevar a efecto las providencias de tramitación, y para la ejecución de las sentencias.','140','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":140,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"eea4c6d4ae07240f37caf9b3c05b05b7a74e9e9bd38517335eac4f8cb8412a8f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','140','eea4c6d4ae07240f37caf9b3c05b05b7a74e9e9bd38517335eac4f8cb8412a8f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:141','mayalex_normativos','09_JUDICIAL','Cuando según las leyes fueren competentes para conocer de un mismo asunto dos o más Jueces o Tribunales, ninguno de ellos podrá excusarse del conocimiento, bajo el pretexto de haber otros Jueces o Tribunales que puedan conocer del mismo asunto; pero el que haya prevenido en el conocimiento, excluye a los demás, los cuales dejan desde entonces de ser competentes.','141','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":141,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"53d7dac73cf06de7753cfc00546f6f4986cc3c6ec7a4838d5f07bdaa1d652919","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','141','53d7dac73cf06de7753cfc00546f6f4986cc3c6ec7a4838d5f07bdaa1d652919','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:142','mayalex_normativos','09_JUDICIAL','La jurisdicción civil podrá prorrogarse a Juez o Tribunal que, por razón de la materia, de la cantidad objeto del litigio y de la jerarquía que tenga en el orden judicial, pueda conocer del negocio que ante él se proponga. La jurisdicción criminal es improrrogable.','142','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":142,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b062956d6b67f3b0a644a18de866a38d09af6435559f5af8e6f667d076b6016a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','142','b062956d6b67f3b0a644a18de866a38d09af6435559f5af8e6f667d076b6016a','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:143','mayalex_normativos','09_JUDICIAL','El Juzgado o Tribunal a que los litigantes se sometieren, expresa o tácitamente, será el competente para conocer de los pleitos y actos a que dé origen el ejercicio de las acciones civiles, siempre que la sumisión se haga en quien tenga jurisdicción para conocer de la misma clase de negocios y en el mismo grado.','143','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":143,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5f0ba7604232ca7c6876bd67b7e334b6576cb2906dc9162c4c51a87c1e80c509","ubicacion":["CAPÍTULO II","DE LA COMPETENCIA EN LO CIVIL","SECCIÓN PRIMERA","REGLAS GENERALES"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','143','5f0ba7604232ca7c6876bd67b7e334b6576cb2906dc9162c4c51a87c1e80c509','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:144','mayalex_normativos','09_JUDICIAL','Se entenderá por sumisión expresa la hecha por los interesados, renunciando clara y terminantemente a su domicilio propio y designando con toda precisión aquél a que se sometieren.','144','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":144,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f03bffcf5fb5905b253e95cf4597aa6d1966fcc2e6372f42c4c16c02c7f44cb0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','144','f03bffcf5fb5905b253e95cf4597aa6d1966fcc2e6372f42c4c16c02c7f44cb0','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:145','mayalex_normativos','09_JUDICIAL','Se entenderá hecha la sumisión tácita:

1. Por el demandante, en el hecho de acudir al Juez interponiendo la demanda.

2. Por el demandado, en el hecho de hacer, después de personado en juicio, cualquier gestión que no sea la de proponer la declinatoria.','145','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":145,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6586edcf42d029ad58570445cff6d08ccfa9c337aa16967e33be968d83f67561","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','145','6586edcf42d029ad58570445cff6d08ccfa9c337aa16967e33be968d83f67561','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:146','mayalex_normativos','09_JUDICIAL','Fuera de los casos de sumisión expresa o tácita de que tratan los artículos anteriores, se seguirán las reglas siguientes de competencia de los negocios civiles:

1. En los juicios en que se ejerciten acciones personales será Juez competente el del lugar en que deba cumplirse la obligación, y a falta de éste, a elección del demandante, el del domicilio del demandado o el del lugar del contrato, si hallándose en él, aunque accidentalmente, pudiere hacerse el emplazamiento.

2. Cuando la demanda se dirija simultáneamente contra dos o más personas que residan en pueblos diferentes, y estén obligadas mancomunada o solidariamente, no habiendo lugar designado para el cumplimiento de la obligación, será Juez competente el del domicilio de cualquiera de los demandados, a elección del demandante.

3. En los juicios en que se ejerciten acciones reales sobre bienes muebles o semovientes, será Juez competente el del lugar en que se hallen o el del domicilio del demandado, a elección del demandante.

4. En los juicios en que se ejerciten acciones reales sobre bienes inmuebles, será Juez competente el del lugar en que esté sita la cosa litigiosa.

Cuando la acción real se ejercite sobre varias cosas inmuebles situadas en diferentes jurisdicciones, pero que se funden en un solo título singular de adquisición, o formen una sola heredad o coto, será Juez competente el de cualquiera de los lugares en cuya jurisdicción estén sitos los bienes, a elección del demandante.

5. En los juicios en que se ejerciten acciones mixtas, será Juez competente el del lugar en que se hallen las cosas o el del domicilio del demandado, a elección del demandante.','146','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":146,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ba19028167efe0cd7f564dc3eb9edff7b902d480ba9d4e62d3acaa3bb7ee0527","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','146','ba19028167efe0cd7f564dc3eb9edff7b902d480ba9d4e62d3acaa3bb7ee0527','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:147','mayalex_normativos','09_JUDICIAL','El domicilio de las mujeres casadas que no estén separadas legalmente de sus maridos, será el que éstos tengan.

El domicilio de los hijos constituidos en potestad, el de sus padres.

El de los menores o incapacitados sujetos a guarda, el de sus guardadores.

Lo dispuesto en los párrafos anteriores se entenderá sin perjuicio de las excepciones establecidas por la Ley, o de lo pactado en las capitulaciones matrimoniales.','147','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":147,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d777357e6ebd521f093b68f51054d442c9495105339efecd92610e90d324ccbe","ubicacion":[],"constancias":[{"nota":51,"tipo":"REFORMA_TACITA","texto":"Artículo 147. Reformado tácitamente por el Código de Familia en el Artículo 15, define el domicilio así. El domicilio de los cónyuges será el del hogar común. Si por cualquier motivo viviese separado, cada cónyuge tendrá su domicilio en el lugar donde tenga su residencia habitual. El domicilio de los hijos será el de sus padres. Si éstos viviesen en lugares diferentes, el domicilio de los hijos será el del padre o madre con quien vivieren. El domicilio de los pupilos será el de sus tutores o guardadores, o de las personas que los tengan a su cargo, según lo establece este Código.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":"CONTEXT","motivo":"REFORMA_TACITA: la edición anota una reforma tácita que el texto no incorpora; CONTEXT hasta dictamen del CLO (D5)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','147','d777357e6ebd521f093b68f51054d442c9495105339efecd92610e90d324ccbe','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:148','mayalex_normativos','09_JUDICIAL','El domicilio legal de los comerciantes en todo lo que concierne a actos o contratos mercantiles y a sus consecuencias, será el pueblo donde tuvieren el centro de sus operaciones comerciales.

Los que tuvieren establecimientos mercantiles a su cargo en diferentes demarcaciones judiciales, podrán ser demandados por acciones personales en aquella en que tuvieren el principal establecimiento, o en la que se hubieren obligado, a elección del demandante.

Respecto a los concursos de acreedores y a las quiebras, se estará a lo prevenido en las reglas 17 y 18 del Artículo 158.

En todo lo que se refiera a operaciones mercantiles, estarán los comerciantes sujetos a lo dispuesto en el Artículo 146.','148','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":148,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a805088fb50a7b255aeea3c8c40a5dc0d0e559acf2ca7a9195eb5322b027d669","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','148','a805088fb50a7b255aeea3c8c40a5dc0d0e559acf2ca7a9195eb5322b027d669','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:149','mayalex_normativos','09_JUDICIAL','El domicilio de las compañías civiles y mercantiles será el pueblo que como tal esté señalado en la escritura de sociedad o en los estatutos por que se rijan.

No constando esta circunstancia, se estará a lo establecido respecto a los comerciantes, en el párrafo segundo del artículo anterior.

Exceptúense de lo establecido en los párrafos anteriores, las compañías en participación, en lo que se refiera a los litigios que puedan promoverse entre los asociados, respecto a los cuales se estará a lo que prescriben las disposiciones generales de esta ley.','149','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":149,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5adfb95560327ddf8d4fb054ee856e155988933b4f30a7e208c215f50f3ebe97","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','149','5adfb95560327ddf8d4fb054ee856e155988933b4f30a7e208c215f50f3ebe97','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:150','mayalex_normativos','09_JUDICIAL','El domicilio legal de los empleados será el pueblo en que sirvieren su destino. Cuando por razón de él ambularen continuamente, se considerarán domiciliados en el pueblo en que vivieren más frecuentemente.','150','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":150,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4f35cdc5a36a87cb55e6afce9dd09cdcff80d53351ccfe60dac16aeef4633b1c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','150','4f35cdc5a36a87cb55e6afce9dd09cdcff80d53351ccfe60dac16aeef4633b1c','OLA12_LOAT_2007_01',now())
