INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:151','mayalex_normativos','09_JUDICIAL','El domicilio legal de los militares en servicio activo será el del pueblo en que se hallare el cuerpo a que pertenezcan al hacerse el emplazamiento.','151','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":151,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"cf2d2e902fa2d46db7edcc68dd956b3ba8703578d13a096dd606e3b1545ae12c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','151','cf2d2e902fa2d46db7edcc68dd956b3ba8703578d13a096dd606e3b1545ae12c','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:152','mayalex_normativos','09_JUDICIAL','En los casos en que esté señalado el domicilio para determinar la competencia, si el que ha de ser demandado no lo estuviese en algún pueblo de la República, será Juez competente el de su residencia.

Los que no tuvieren domicilio ni residencia fija, podrán, ser demandados en el lugar en que se hallen, o en el de su última residencia, a elección del demandante.','152','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":152,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b4987e41d7a82626eeaf956dccb84c0e6b5cf7d7ff6f1e70c5965a2df3880f97","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','152','b4987e41d7a82626eeaf956dccb84c0e6b5cf7d7ff6f1e70c5965a2df3880f97','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:153','mayalex_normativos','09_JUDICIAL','El valor de las demandas para determinar por él la competencia de jurisdicción, se calculará por las reglas siguientes:

1. En los juicios petitorios sobre el derecho de exigir prestaciones anuales y perpetuas, se calculará el valor por el de una anualidad multiplicada por 25.

2. Si la prestación fuere vitalicia, se multiplicará por 10 la anualidad.

3. En las obligaciones pagaderas a plazos diversos, se calculará el valor por el de toda la obligación, cuando el juicio verse sobre la validez del principio mismo de que proceda la obligación en su totalidad.

4. Cuando varios créditos pertenecieren a diversos interesados y procedieren de un mismo título de obligación, contra un deudor común, la demanda que cada acreedor, o dos o más acreedores entablaren por separado, para que se les pague lo que les corresponda, se calculará como valor de la demanda la cantidad a que ascienda la reclamación.

5. En las demandas sobre servidumbres, se calculará su cuantía por el precio de adquisición de las mismas servidumbres, si constare.

6. En las acciones reales o mixtas, se calculará el valor de la cosa inmueble o litigiosa, por el que conste en la escritura más moderna de su enajenación.

Cuando por medio de la acción real o mixta se demanden con los bienes las rentas que hayan producido, se acumularán éstas al valor de la demanda.

7. En las demandas que comprendieren muchos créditos contra el mismo deudor, se calculará su cuantía por el de todos los créditos reunidos.

8. En los pleitos sobre pago de créditos con intereses o frutos, si en la demanda se pidieren con el principal los vencidos y no pagados, se hará la computación sumando entre sí el uno y los otros.

Se tendrá por cierta y líquida la cuantía de los frutos cuanto el actor expresare en la demanda su importe anual y el tiempo que haya transcurrido sin pagarse.

Si el importe de o los intereses o frutos no fuere cierto y líquido, se prescindirá de él no tomando en cuenta más que el principal.

9. La disposición de la regla precedente es aplicable al caso en que se pidan en la demanda, con el principal, los perjuicios.

10. Para la fijación del valor de la demanda no se tomarán en cuenta los frutos o intereses por correr sino los corridos.

11. Cuando por los datos expresados en las reglas anteriores no pudiere determinarse el valor de la demanda, se estimará por el que le dieren las partes de conformidad, y estando discordes, por el que estime un perito nombrado de común acuerdo por las mismas.

Si no se pusieren de acuerdo sobre la elección de un solo perito, nombrará uno cada parte, y el Juez un tercero, para que juntos aquéllos hagan la valoración, dirimiendo el tercero la discordia, si la hubiere.','153','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":153,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"53e205cf7c93fe3a8a27b56d200d0a7136df28d8bcdfdec20716e77133243928","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','153','53e205cf7c93fe3a8a27b56d200d0a7136df28d8bcdfdec20716e77133243928','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:154','mayalex_normativos','09_JUDICIAL','Cuando no pueda determinarse según las reglas del artículo anterior la cuantía de la demanda, no caerá bajo la competencia de la jurisdicción de los Jueces y Tribunales que la tengan limitada por razón de cantidad.','154','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":154,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8ff6341b13f4453393297148f45956cbf9283ed48d90642108813a04b947f0ca","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','154','8ff6341b13f4453393297148f45956cbf9283ed48d90642108813a04b947f0ca','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:155','mayalex_normativos','09_JUDICIAL','Lo establecido en el Artículo 153 no se aplicará a las demandas relativas a derechos políticos u honoríficos, exenciones personales, filiación, paternidad, maternidad, tutela, curaduría, interdicción y cualquier otra que verse sobre el estado civil y condición de las personas.','155','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":155,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f25534e31bd7aa6527728eb8052e2542019ed8eaf4c851add33f8003c8be70ef","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','155','f25534e31bd7aa6527728eb8052e2542019ed8eaf4c851add33f8003c8be70ef','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:156','mayalex_normativos','09_JUDICIAL','Lo establecido en este Capítulo comprenderá a los extranjeros que acudieren a los Juzgados y Tribunales hondureños, promoviendo actos de jurisdicción voluntaria, interviniendo en ellos o compareciendo en juicio como demandantes o como demandados, contra hondureños o contra otros extranjeros, cuando proceda que conozca la jurisdicción hondureña con arreglo a las leyes de la República o a los Tratados con otras Potencias.','156','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":156,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"61b4fdc245f290b164b19aefa8804fb4fc47d5d8f298871e49787b1e03cc72df","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','156','61b4fdc245f290b164b19aefa8804fb4fc47d5d8f298871e49787b1e03cc72df','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:157','mayalex_normativos','09_JUDICIAL','Se estará a lo que establezcan las leyes especiales que en determinados negocios fijen otras reglas de competencia.','157','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":157,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f1f8201fce9db26a1e70ded0e9d673b493edf67380d5a08ed10feeb078dcfb1d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','157','f1f8201fce9db26a1e70ded0e9d673b493edf67380d5a08ed10feeb078dcfb1d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:158','mayalex_normativos','09_JUDICIAL','No obstante las reglas establecidas en el Artículo 146, se observarán en los negocios y causas civiles que a continuación se expresan, las siguientes:

15. En las demandas sobre estado civil, será Juez competente el del domicilio del demandado.

15. En los depósitos de personas, será Juez competente el que conozca del pleito o causa que los motive.

Cuando no hubiere autos anteriores, será Juez competente el del domicilio de la persona que deba ser depositada.

Cuando circunstancias particulares lo exigieren, podrá decretar interina y provisionalmente el depósito el Juez de Paz del lugar en que se encontrare la persona que deba ser depositada, remitiendo las diligencias al Juez del domicilio, y poniendo a su disposición la persona depositada.

3. En las cuestiones de alimentos, cuando éstos se pidan incidentalmente, en los casos de depósitos de personas, o en juicio, será competente el Juez que conozca de los autos.

Cuando los alimentos sean el objeto principal de un juicio, será Juez competente el del lugar en que tenga su domicilio aquel a quien se pidan.

4. En el nombramiento y discernimiento de los cargos de tutores y curadores para los bienes, y excusas de estos cargos, será Juez competente el del domicilio del padre o de la madre cuya muerte ocasionare el nombramiento, y, en su defecto, el Juez del domicilio del menor o del incapacitado, o el de cualquier lugar en que tuviere bienes inmuebles.

5. En el nombramiento y discernimiento de los cargos de curadores para pleitos, será Juez competente el del lugar en que los menores o incapacitados necesitaren comparecer en juicio.

6. En las demandas en que se ejercitaren acciones relativas a la gestión de la tutela o curaduría, en las excusas de estos cargos después de haber empezado a ejercerlos, y en las demandas de remoción de los guardadores, como sospechosos, será Juez competente el del lugar en que se hubiere administrado la guarda en su parte principal, o el del domicilio del menor.

7 En las autorizaciones para la venta de bienes de menores o incapacitados, será Juez competente, el del lugar en que los bienes se administren, o el del domicilio de aquellos a quienes pertenecieren.

8 En las informaciones para dispensas de ley y en las habilitaciones para comparecer en juicio, cuando por derecho se requieran, será Juez competente el del domicilio del que las solicitare.

9. En las informaciones para perpetua memoria, será Juez competente el del lugar o lugares en que hayan ocurrido los hechos, o aquel en que estén, aunque sea accidentalmente, los testigos que hayan de declarar.

Cuando estas informaciones se refieran al estado actual de cosas inmuebles, será Juez competente el del lugar en que estuvieren sitas.

10. En las demandas deducidas en juicio sobre obligaciones de garantía o complemento de otras anteriores, será Juez competente el del lugar en que se conozca de la obligación principal sobre que recayeren.

11. En las demandas de reconvención, será Juez competente el del lugar en que se hubiere interpuesto la con que se hubiese promovido el litigio.

No es aplicable esta regla cuando el valor de lo pedido en la reconvención excediere de la cuantía a que alcancen las atribuciones del Juez que entendiere en la principal demanda, en cuyo caso reservará éste al autor de la reconvención su derecho para que lo ejercite donde corresponda.

12. En las demandas en que se ejercite la acción de desahucio, será Juez competente el del lugar donde estuviere sita la cosa que dé ocasión al juicio, o el del domicilio del demandado, a elección del demandante.

13. En el juicio de petición de herencia, será Juez competente el del lugar en que, con arreglo a lo dispuesto en el Artículo 934 del Código Civil, se hubiere abierto la sucesión del difunto.

14. En los interdictos de amparo, de restitución, de restablecimiento y especiales, en las denuncias de obra nueva y obra ruinosa, y en los deslindes, será Juez competente el del lugar en que esté sita la cosa objeto del interdicto o deslinde.

15. En las diligencias para elevar a escritura pública los testamentos menos solemnes, y en las que hayan de practicarse para la apertura de los testamentos cerrados, será Juez competente el del lugar en que se hubiesen otorgado, respectivamente, los testamentos o las cubiertas, o el del domicilio del testador, a elección del interesado; sin perjuicio de los dispuesto en el Artículo 1025 del Código Civil.

16. El Juez del lugar donde se hubiere abierto la sucesión será competente para conocer de todas las diligencias judiciales relativas a la formación de inventarios, tasación y partición de los bienes que el difunto hubiere dejado.

Si el difunto hubiere tenido su último domicilio en país extranjero, será Juez competente el del lugar en que hubiese tenido el finado su último domicilio en Honduras, o el del lugar donde estuviere la mayor parte de sus bienes.

No obstará esto para que los Jueces y Tribunales de la demarcación en que tuviere bienes el difunto, tomen las medidas necesarias para asegurarlos y poner en buena guarda los libros y papeles, remitiendo las diligencias practicadas a los Jueces a quienes corresponda conocer de la apertura de la sucesión, y dejándoles expedita su jurisdicción.

17. En los concursos de acreedores y en las quiebras, cuando fuere voluntaria la presentación del deudor, será Juez competente el del domicilio del mismo.

18. En los concursos o quiebras promovidas por los acreedores, el de cualquiera de los lugares en que se esté conociendo en las ejecuciones.

Será entre ellos preferido el del domicilio del deudor, si éste o el mayor número de acreedores lo reclamaren. En otro caso, lo será aquel en que antes se decretase el concurso o la quiebra.

19. En la acumulación de autos correspondientes a diferentes Juzgados o Tribunales, cuando proceda según las leyes, será competente el que conociere de los más antiguos.

Exceptúense los autos de sucesión hereditaria, concurso de acreedores y quiebras, en los cuales la acumulación de todos los juicios especiales se hará siempre al universal.

Lo dispuesto en los dos párrafos anteriores no es aplicable a los autos que estuvieren en diferentes instancias y en los conclusos para sentencias, los cuales no serán acumulables.

20. En los litigios acerca de recusación de Árbitros y de amigables componedores, cuando ellos no accediesen a la recusación, será competente: el Juez del lugar en que resida el recusado, o el del en que se hubiere otorgado la escritura de compromiso, a elección del recurrente.

21. En los recursos de apelación contra los Árbitros, en los casos en que corresponda según derecho, será competente la Corte de Apelaciones a que corresponde el pueblo en que se haya fallado el pleito.

22. En los embargos preventivos será competente el Juez de la demarcación en que estuvieren los bienes que se hubieren de embargar, y a prevención en los casos de urgencia, el Juez de Paz del pueblo en que se hallasen.','158','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":158,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"62705b8c084d8dc27c41572304d823b816528e7d8e08b15c41555e82f51449ce","ubicacion":["SECCIÓN SEGUNDA","REGLAS ESPECIALES"],"constancias":[{"nota":52,"tipo":"REFERENCIA","texto":"Artículo 158 numeral 11). Debería leerse: En las demandas de reconvención, será competente del lugar en que se hubiere interpuesto la demanda con que se hubiese promovido el litigio.","decretos":[]},{"nota":53,"tipo":"REFERENCIA","texto":"Artículo 934. Código Civil La sucesión en los bienes de una persona se abre al momento de muerte o en su último domicilio, salvo los casos expresamente exceptuados.","decretos":[]},{"nota":54,"tipo":"REFERENCIA","texto":"Artículo 1025. Código Civil. La información de que habla los dos (2) artículo precedentes, será remitida al Juez de Letras del último domicilio, si no lo fuere el que ha recibido la información; y el Juez, si encontrare que se han observado las solemnidades prescritas, y que en la información aparece claramente la última voluntad del testador, fallará que, según dicha información, el testador ha hecho las declaraciones y disposiciones siguientes, ( expresándolas); y mandará que valgan dichas declaraciones y disposiciones como testamento del difunto, y que se protocolice el expediente. No se mirarán como declaraciones y disposiciones testamentarias sino aquellas en que los testigos que asistieron por vía de solemnidad estuvieren conformes.","decretos":[]},{"nota":55,"tipo":"REFERENCIA","texto":"Artículo 158 numeral 20) Según “Ley de Conciliación y Arbitraje”,Decreto No. 161-2000 de fecha 17 de octubre de 2000, publicado en el Diario Oficial la Gaceta No. 29404, de fecha 14 de febrero del 2001.","decretos":["161-2000"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','158','62705b8c084d8dc27c41572304d823b816528e7d8e08b15c41555e82f51449ce','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:159','mayalex_normativos','09_JUDICIAL','La jurisdicción ordinaria conocerá de todas las causas criminales, con la sola excepción de las que con arreglo a las leyes correspondan a la jurisdicción militar.','159','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":159,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"42732a2eb209520500bb0a6a1d8111fbd7c6fb936576d59fd2894b49b07c644b","ubicacion":["CAPÍTULO III","DE LA COMPETENCIA EN LO CRIMINAL"],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','159','42732a2eb209520500bb0a6a1d8111fbd7c6fb936576d59fd2894b49b07c644b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:160','mayalex_normativos','09_JUDICIAL','El conocimiento de las causas por delitos militares, cualesquiera que sean las personas culpables corresponderá exclusivamente a la jurisdicción militar.','160','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":160,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"2886e9e0ca9e2c14bbdb130d9adefb1938e60f0deda60dcef233da90391faa4e","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','160','2886e9e0ca9e2c14bbdb130d9adefb1938e60f0deda60dcef233da90391faa4e','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:161','mayalex_normativos','09_JUDICIAL','La jurisdicción ordinaria será competente para prevenir las causas por delitos militares.

Esta competencia se limitará a instruir las primeras diligencias, concluidas las cuales, la jurisdicción ordinaria remitirá las actuaciones al Juez que debiere conocer de la causa con arreglo a las leyes, y pondrá a su disposición a los detenidos y los efectos ocupados.

La jurisdicción ordinaria cesará en las primeras diligencias, tan luego como conste que la especial competente forma causa sobre el mismo delito.

Considérense como primeras diligencias las que se determinan en el artículo 34.','161','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":161,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"c2efb0979664b3883583445346162b93ea57d3d117cb17e0301fa4cb0e05431d","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','161','c2efb0979664b3883583445346162b93ea57d3d117cb17e0301fa4cb0e05431d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:162','mayalex_normativos','09_JUDICIAL','Fuera de los casos reservados a la Corte Suprema y a las Cortes de Apelaciones, serán competentes para la instrucción de las causas y castigo de los delitos y de las faltas, los Jueces de Letras y los Jueces de Paz de la demarcación en que se hayan cometido, según su respectiva competencia.','162','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":162,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"552133e30a93ecc31ca364235c23b206e9143b8327b85a1686335fe747e07fdf","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','162','552133e30a93ecc31ca364235c23b206e9143b8327b85a1686335fe747e07fdf','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:163','mayalex_normativos','09_JUDICIAL','Cuando no conste el lugar en que se cometió una falta o un delito, serán Jueces y Tribunales competentes para instruir y conocer de la causa:

1. El de la demarcación en que se hayan descubierto pruebas materiales del delito.

2. El de la demarcación en que el reo presunto haya sido aprehendido.

3. El de la residencia del reo presunto.

4. Cualquiera que hubiere tenido noticia del delito.

Si se suscitare competencia entre estos Jueces y Tribunales, se decidirá dando preferencia por el orden en que están expresados en el párrafo precedente.

Tan luego como conste el lugar en que se hubiere cometido el delito, se remitirán las actuaciones al Juzgado o Tribunales de aquella demarcación, poniendo a su disposición a los detenidos y efectos ocupados.','163','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":163,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a1e151e1b1df6cc17201783c7692047335130d0fafab0a7ebbf383b4ba000dde","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','163','a1e151e1b1df6cc17201783c7692047335130d0fafab0a7ebbf383b4ba000dde','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:164','mayalex_normativos','09_JUDICIAL','El Juez o Tribunal competente para la instrucción o conocimiento de una causa, lo será también para conocer de la complicidad en el delito que se persiga, de su encubrimiento y de las incidencias de aquélla.','164','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":164,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"fe0cdcb27f07ff839e863924df3c3684af407e5339ca04f6863e6d98c35173c3","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','164','fe0cdcb27f07ff839e863924df3c3684af407e5339ca04f6863e6d98c35173c3','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:165','mayalex_normativos','09_JUDICIAL','Un solo Juez o Tribunal de los que sean competentes, conocerá de los delitos que tengan conexión entre sí.','165','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":165,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"24ebab607b167cb09a1fed0fd2cf6b8621a8b8b9305ae5a692b46dc82e205eee","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','165','24ebab607b167cb09a1fed0fd2cf6b8621a8b8b9305ae5a692b46dc82e205eee','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:166','mayalex_normativos','09_JUDICIAL','El conocimiento de los delitos conexos corresponderá a la jurisdicción militar, cuando alguno de estos delitos esté sujeto a dicha jurisdicción.','166','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":166,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"5d377523c5f216b60caf6cd4e427e493ddda7bb08e50bb4d175fdf4cb60098c1","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','166','5d377523c5f216b60caf6cd4e427e493ddda7bb08e50bb4d175fdf4cb60098c1','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:167','mayalex_normativos','09_JUDICIAL','Lo establecido en el artículo anterior se entiende en el caso de que sea competente la jurisdicción militar para juzgar de los delitos conexos.

Si alguno de éstos fuere por su índole y naturaleza de la competencia exclusiva de la jurisdicción ordinaria, ésta deberá conocer de la causa que se forme sobre él, sin perjuicio de que la militar conozca de la que se instruya sobre los demás.','167','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":167,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"c8799bfd7c251d82bf0191b0f9f86ad143e65bc2668194bf829ba9e4c04a2ae5","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','167','c8799bfd7c251d82bf0191b0f9f86ad143e65bc2668194bf829ba9e4c04a2ae5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:168','mayalex_normativos','09_JUDICIAL','Considéranse delitos conexos:

1. Los cometidos simultáneamente por dos o más personas reunidas.

2. Los cometidos por dos o más personas en distintos lugares o tiempos, si hubiese precedido concierto para ello.

3. Los cometidos como medio para perpetrar otros o facilitar su ejecución.

4. Los cometidos para procurar la impunidad de otros delitos.','168','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":168,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"0e25f9bd6f7d49a93664670d26d0d28d3d3874bc9f1ef5e752379aade7cbbfa3","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','168','0e25f9bd6f7d49a93664670d26d0d28d3d3874bc9f1ef5e752379aade7cbbfa3','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:169','mayalex_normativos','09_JUDICIAL','Son Jueces y Tribunales competentes, por su orden, para conocer de las causas por delitos conexos:

1. El del territorio en que se haya cometido el delito a que esté señalada pena mayor.

2. El que primero comenzare la causa, en el caso de que a los delitos esté señalada igual pena.

3. El que la Corte de Apelaciones, atendiendo sólo a la mejor y más pronta administración de Justicia, designe en sus casos respectivos, cuando las causas hubieren empezado al mismo tiempo, o no conste cuál comenzó primero, si los Juzgados o Tribunales correspondieren al territorio de la misma Corte.

4. El que la Corte Suprema, teniendo también en cuenta sólo la mejor y más pronta administración de justicia, designe en el caso del párrafo anterior, si las causas hubieren empezado en Juzgados o Tribunales que correspondan a diferentes Cortes de Apelaciones.','169','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":169,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"50c575b9612de73318f5d3040c48d52db481d1d7a0bf0fb5c53bdec03fc4acd6","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','169','50c575b9612de73318f5d3040c48d52db481d1d7a0bf0fb5c53bdec03fc4acd6','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:170','mayalex_normativos','09_JUDICIAL','Los extranjeros que cometieren faltas o delinquieren en Honduras, serán juzgados por los que tengan competencia para ello.','170','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":170,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"cd12d23ffa66f3e0048ade7a448aa705cb41bfe83efd46b1442223e0aeb057f9","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','170','cd12d23ffa66f3e0048ade7a448aa705cb41bfe83efd46b1442223e0aeb057f9','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:171','mayalex_normativos','09_JUDICIAL','Exceptúense de lo ordenado en el artículo anterior, los Jefes de otros Estados y los substitutos de éstos, los Ministros Plenipotenciarios, los Ministros Residentes, los Encargados de Negocios, y los extranjeros empleados de planta en las Legaciones, los cuales, cuando delinquieren, serán puestos a disposición de sus Gobiernos respectivos.','171','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":171,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"e714935c16427e45dca00330639270fbe5d13b9b6ab17fad007679c3af2b09a3","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','171','e714935c16427e45dca00330639270fbe5d13b9b6ab17fad007679c3af2b09a3','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:172','mayalex_normativos','09_JUDICIAL','El conocimiento de los delitos comenzados a cometer en Honduras, y consumados o frustrados en países extranjeros, corresponderá a los Tribunales y Jueces hondureños, en el caso de que los actos perpetrados en Honduras constituyan por sí delito, y sólo respecto a éstos.','172','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":172,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"62aeb229a542682f198fb74c78d7e4642eda92e51dcfd0713ad058a0e9acfc47","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','172','62aeb229a542682f198fb74c78d7e4642eda92e51dcfd0713ad058a0e9acfc47','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:173','mayalex_normativos','09_JUDICIAL','Serán juzgados por los Jueces y Tribunales de la República, según el orden prescrito en el Artículo 163, los hondureños o extranjeros que fuera del territorio de la Nación hubiesen cometido alguno de los delitos siguientes:

-Contra la seguridad exterior o interior del Estado.

-Contra el Presidente de la República.

-Rebelión.

-Falsificación de la firma o de la estampilla del Presidente de la República.

-Falsificación de las firmas de los Ministros.

-Falsificación de sellos públicos.

-Falsificación que perjudique directamente el crédito o intereses del Estado, y la introducción o expedición de lo falsificado.

-Falsificación de moneda o de billetes de banco, cuya emisión esté autorizada por la ley, y la introducción o expedición de los falsificados.

-Los cometidos en el ejercicio de sus funciones por empleados públicos residentes en territorio extranjero.','173','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":173,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"35bbf728aed5c26209ce8bef5e5f4fa10bd70941c1f92234f58bca9e20e9ff20","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','173','35bbf728aed5c26209ce8bef5e5f4fa10bd70941c1f92234f58bca9e20e9ff20','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:174','mayalex_normativos','09_JUDICIAL','Si los reos de los delitos comprendidos en el artículo anterior hubieren sido absueltos o penados en el extranjero, siempre que en este último caso se hubiese cumplido la condena, no se abrirá de nuevo la causa.

Lo mismo sucederá si hubiesen sido indultados, a excepción de los delitos contra la seguridad exterior del Estado o contra el Presidente de la República.

Si hubieren cumplido parte de la pena, se tendrá en cuenta para rebajar proporcionalmente la que en otro caso les correspondería.','174','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":174,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"c91f72633b87d291aa29c2d61cc7a17362487aef99fd64edb1bface77febe01f","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','174','c91f72633b87d291aa29c2d61cc7a17362487aef99fd64edb1bface77febe01f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:175','mayalex_normativos','09_JUDICIAL','Lo dispuesto en los dos artículos que anteceden es aplicable a los extranjeros que hubiesen cometido alguno de los delitos comprendidos en ellos, cuando fueren aprehendidos en el territorio hondureño o se obtuviese la extradición.','175','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":175,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"9e511c8c41c25f8717a36c9f90b1248bd8cdf2777cffab939e5434437c3178ad","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','175','9e511c8c41c25f8717a36c9f90b1248bd8cdf2777cffab939e5434437c3178ad','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:176','mayalex_normativos','09_JUDICIAL','El hondureño que cometiere un delito en país extranjero contra otro hondureño, será juzgado en Honduras por los Juzgados o Tribunales designados en el Artículo 163, y por el mismo orden con que se designen, si concurrieren las circunstancias siguientes:

1. Que se querelle el ofendido o cualquiera de las personas que puedan hacerlo con arreglo a las leyes.

2. Que el delincuente se halle en territorio hondureño.

3. Que el delincuente no haya sido absuelto, indultado o penado en el extranjero, y en este último caso haya cumplido su condena.

Si hubiere cumplido parte de la pena, se observará lo que para igual caso previene el Artículo 174.','176','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":176,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"59015006ad3ef795fe5add93b93e8ed246e8aecb04ad3aed0ce36f7ffc3cfe0e","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','176','59015006ad3ef795fe5add93b93e8ed246e8aecb04ad3aed0ce36f7ffc3cfe0e','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:177','mayalex_normativos','09_JUDICIAL','El hondureño que cometiere en país extranjero un delito de los que el Código Penal hondureño califica de graves, contra un extranjero será juzgado en Honduras si concurren las tres circunstancias señaladas en el artículo que precede, y por los mismos Jueces que en él se designan.','177','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":177,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"3e432aa4fb5155e3162d1aab06728c558a5ab9c22d91f97a252058462c39f8b5","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','177','3e432aa4fb5155e3162d1aab06728c558a5ab9c22d91f97a252058462c39f8b5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:178','mayalex_normativos','09_JUDICIAL','No podrá procederse criminalmente en el caso del artículo anterior, cuando el hecho de que se trate no sea delito en el país en que se perpetró, aunque lo sea según las leyes de Honduras.','178','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":178,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ad9a510e6af47add3088dca5b6ca55150999af6d3ba36b3ce4f23c04da0c923d","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','178','ad9a510e6af47add3088dca5b6ca55150999af6d3ba36b3ce4f23c04da0c923d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:179','mayalex_normativos','09_JUDICIAL','Los hondureños que delincan en país extranjero y sean entregados a los Cónsules de Honduras, serán juzgados con sujeción a esta ley, en cuanto lo permitan las circunstancias locales.

Instruirá el proceso en primera instancia el Cónsul o el que le reemplace, si no fuere letrado, con el auxilio de un Asesor, y en su defecto, con el de dos Adjuntos elegidos entre los ciudadanos hondureños, los cuales serán nombrados por él al principio de cada año y actuarán en todas las causas pendientes o incoadas durante el mismo.

Terminada la instrucción de la causa, y ratificadas a presencia del reo o reos presuntos las diligencias practicadas, se remitirán los autos al Juzgado o Tribunal hondureño que, atendida la naturaleza del delito, tenga competencia para conocer de él, y sea el más próximo al Consulado en que se haya seguido la causa.','179','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":179,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a08672a994cd0b65eab0785623e8e629f389b08b10330264b3c3ea93eea4413f","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','179','a08672a994cd0b65eab0785623e8e629f389b08b10330264b3c3ea93eea4413f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:180','mayalex_normativos','09_JUDICIAL','La jurisdicción ordinaria es competente para conocer de las faltas, sin más excepciones que las faltas militares y las de policía.','180','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":180,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"d8a8a2dc5f30350aacee1e21400284dffc1c64340ef9d4b1c05dfde76d17354f","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','180','d8a8a2dc5f30350aacee1e21400284dffc1c64340ef9d4b1c05dfde76d17354f','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:181','mayalex_normativos','09_JUDICIAL','Los Jueces del lugar en que se cometa una falta son los únicos competentes para juzgarla.','181','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":181,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6ecc80505d9feee4c3a0fee3ea06d9e389d56efcb91bf3f1a2c08019736d7453","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','181','6ecc80505d9feee4c3a0fee3ea06d9e389d56efcb91bf3f1a2c08019736d7453','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:182','mayalex_normativos','09_JUDICIAL','En las faltas cometidas en país extranjero, en que sean entregados los que las cometan a los Cónsules hondureños, juzgará en primera instancia el Vicecónsul, si lo hubiere, y en apelación, el Cónsul con su Asesor, si no fuere letrado, y a falta de Asesor, con los Adjuntos de que habla el Artículo 179. Si no hubiere Vicecónsul, hará sus veces un ciudadano hondureño, elegido del mismo modo que los Adjuntos, al principio de cada año.

Estos juicios se seguirán en conformidad a las leyes de la República.','182','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":182,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"984c016759588b7b9378ea5c25d536e298c7adf414cb6576daceaff1afa3bd75","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','182','984c016759588b7b9378ea5c25d536e298c7adf414cb6576daceaff1afa3bd75','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:183','mayalex_normativos','09_JUDICIAL','Lo prescrito en este Capítulo, respecto a delitos cometidos en el extranjero, se entenderá sin perjuicio de los Tratados vigentes, o que en adelante se celebraren con Potencias extranjeras.','183','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":183,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"ae2899ea9d2eb72f3cb5d9db6ef2d52492d17c179d65bda8c3ea7d7eda53f738","ubicacion":[],"constancias":[{"nota":56,"tipo":"REFERENCIA","texto":"Artículo 159 al 183. Véase en Materia Penal sobre los sujetos procesales, de los juzgados y tribunales, jurisdicción, competencia por razón de la materia y de la función, por conexión, el Título III CAPÍTULO I del Código Procesal Penal Decreto 9-99 E.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','183','ae2899ea9d2eb72f3cb5d9db6ef2d52492d17c179d65bda8c3ea7d7eda53f738','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:184','mayalex_normativos','09_JUDICIAL','De la competencia que se suscitare entre dos Jueces de Paz, conocerá el Juez de Letras de quien aquéllos dependan.

Si la competencia se suscitare entre dos Jueces de Letras, o entre un Juez de Letras y un Juez de Paz, conocerá la Corte de Apelaciones de quien dependan.','184','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":184,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4e7da7acfd8bd0a536e0a65f1768c514426d240ff96a4a990dcca5ef1590331b","ubicacion":["CAPÍTULO IV","DE LAS CUESTIONES DE COMPETENCIA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','184','4e7da7acfd8bd0a536e0a65f1768c514426d240ff96a4a990dcca5ef1590331b','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:185','mayalex_normativos','09_JUDICIAL','Las cuestiones de competencia que se suscitaren entre las autoridades judiciales, fuera de los casos enunciados en el artículo anterior, serán resueltas por el superior común, y las que se suscitaren entre autoridades administrativas y judiciales, serán resueltas por la Corte Suprema.','185','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":185,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"1de9478c05102d135bd1742b4dec5505d32acfb9192d5c9b3f67bfbcc63a4eca","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','185','1de9478c05102d135bd1742b4dec5505d32acfb9192d5c9b3f67bfbcc63a4eca','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:186','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados, cualquiera que sea su jerarquía, sólo podrán ser recusados por causa legítima.','186','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":186,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b9338a1120e6b29613391e0697d543a3b6ba81c7ed8b57d087993b781678e738","ubicacion":["TITULO XII","DE LA REACUSACIÓN","DE LOS JUECES Y MAGISTRADOS","CAPÍTULO I","DE LAS CAUSAS DE REACUSACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','186','b9338a1120e6b29613391e0697d543a3b6ba81c7ed8b57d087993b781678e738','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:187','mayalex_normativos','09_JUDICIAL','Podrán sólo recusar, en los negocios civiles, los que sean o se muestren parte en ellos. En los negocios criminales:
-El representante del Ministerio Público.
-El acusador privado, o los que por él puedan ejercitar o ejerciten sus acciones y derechos.
-Los procesados.
-Los responsables civilmente por delito o falta.','187','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":187,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"f1a59285050b1f6fd20dfbb1586c6b1cb9be9b8770dda9c6649eeb50b9888af8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','187','f1a59285050b1f6fd20dfbb1586c6b1cb9be9b8770dda9c6649eeb50b9888af8','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:188','mayalex_normativos','09_JUDICIAL','Son causas legítimas de recusación:

1. El parentesco dentro del cuarto grado de consanguinidad o segundo de afinidad con cualquiera de los expresados en el artículo anterior.

2. El mismo parentesco dentro del segundo grado de consanguinidad o afinidad con el Abogado o Procurador de alguna de las partes que intervengan en el pleito o en la causa.

3. Estar o haber sido denunciado o acusado por alguna de ellas como autor, cómplice o encubridor de un delito, o como autor de una falta.

4. Haber sido defensor de alguna de las partes, emitido dictamen sobre el pleito o proceso, o alguna de sus incidencias, como letrado, o intervenido en él como Fiscal, perito o testigo.

5. Ser o haber sido denunciador o acusador privado del que recusa.

6. Ser o haber sido tutor o curador de alguno que sea parte en el pleito o en la causa.

7. Haber estado en tutela o curaduría de alguno de los expresados en el número anterior.

8. Tener pleito pendiente con el recusante.

9. Tener interés directo o indirecto en el pleito o en la causa.

10. Amistad íntima.

11. Enemistad manifiesta.','188','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":188,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a00f7c083927ed3c52c216d76565b65f48ce891c4dfd315205176415a35fc02d","ubicacion":[],"constancias":[{"nota":57,"tipo":"REFERENCIA","texto":"Sobre las Recusaciones de los Jueces y Magistrados. Véase CAPÍTULO II Sección Sexta, Artículo 83 al 91 del Código Procesal Penal, Decreto 9-99 E del 19 de diciembre de 1999.","decretos":["9-99"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','188','a00f7c083927ed3c52c216d76565b65f48ce891c4dfd315205176415a35fc02d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:189','mayalex_normativos','09_JUDICIAL','Los Jueces y Magistrados comprendidos en el artículo anterior deberán excusarse del conocimiento del negocio sin esperar a que se les recuse.

Contra estas excusas no habrá recurso alguno; pero si fueren indebidas, quedarán sujetas a las correcciones disciplinarias, en la forma que determina el Código de Procedimientos.','189','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":189,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b2386ade8a7e6c392e5eee902d375f8833f133db1990789d7b456756eddcf5c6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','189','b2386ade8a7e6c392e5eee902d375f8833f133db1990789d7b456756eddcf5c6','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:190','mayalex_normativos','09_JUDICIAL','La recusación en los negocios civiles se propondrá en el primer escrito que presente el recusante, cuando la causa en que se funde fuere anterior al pleito o tenga de ella conocimiento.

Cuando fuere posterior, o aunque anterior, no hubiere tenido antes de ella conocimiento, el recusante la deberá proponer tan luego como llegue a su noticia.','190','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":190,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"51c8e0951e3e31aa005c09c315bdcc4b595fab1ebc86a6a290979247f02fd755","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','190','51c8e0951e3e31aa005c09c315bdcc4b595fab1ebc86a6a290979247f02fd755','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:191','mayalex_normativos','09_JUDICIAL','En lo criminal podrá proponerse la recusación en cualquier estado de la causa.','191','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":191,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"6b21df7d793d8ef9761f0674da352a6d618817c75eea53bcbb5622b0c577a992","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','191','6b21df7d793d8ef9761f0674da352a6d618817c75eea53bcbb5622b0c577a992','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:192','mayalex_normativos','09_JUDICIAL','Ni en lo civil ni en lo criminal podrá hacerse recusación después de comenzada la vista, o de la citación para sentencia.','192','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":192,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"7171b90ba35619a5bc780544441f74338117584a3690f288f2a7cb10e019486d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','192','7171b90ba35619a5bc780544441f74338117584a3690f288f2a7cb10e019486d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:193','mayalex_normativos','09_JUDICIAL','De la recusación de los Jueces de Letras y de los Jueces de Paz conocerá el funcionario llamado por la ley a subrogarlos, y procederá el recurso de apelación cuando se denegare.

De la recusación de los Magistrados de la Corte Suprema y de las Cortes de Apelaciones conocerá el Tribunal mismo, con exclusión del miembro o miembros de cuya recusación se trate, y cuando se denegare, sólo procederá el recurso de casación en su caso.','193','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":193,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"fb5618e59885dd76dce149e65f06c0e10a7f18c7f491352e51dead65c394cdfa","ubicacion":["CAPÍTULO II","DE LAS CUESTIONES DE REACUSACIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','193','fb5618e59885dd76dce149e65f06c0e10a7f18c7f491352e51dead65c394cdfa','OLA12_LOAT_2007_01',now()),
