INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:251','mayalex_normativos','09_JUDICIAL','Los que pretendan ejercer la profesión de Procuradores, se presentarán ante la Corte Suprema con el título obtenido conforme al Código de Instrucción Pública, solicitando la correspondiente autorización. La Corte mandará practicar las diligencias siguientes:

1. Información de dos o más testigos, propietarios, de conocida probidad, sin tacha legal y que conozcan al pretendiente sobre si concurren en éste las circunstancias a que se refiere el artículo anterior.

2. Examen público sobre las materias de la Procuración y práctica forense y en general sobre los deberes anexo al oficio de Procurador; debiendo el Tribunal resolver la aprobación o reprobación del pretendiente.

Si fuere favorable el resultado de estas diligencias, la Corte concederá la autorización solicitada, debiendo el solicitante prestar la promesa de ejercer bien y fielmente la profesión.','251','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":251,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"378f03311a010f08481bf4fe4bbfe4bf1a477eaa29473812cc14815a35271152","ubicacion":[],"constancias":[{"nota":69,"tipo":"REFORMA","texto":"Artículos 250, 251 y 252. Los Artículos 11 y 12 de la Ley Orgánica del Colegio de Abogados de Honduras decreto 18 del 28 de septiembre de 1965 publicado en el diario Oficial La Gaceta No. 18,686 del 8 de octubre de 1965, y el Reglamento para el ejercicio de la Procuración aprobado en Asamblea Ordinaria el 1 de enero de 1971, establecen los requisitos para el ejercicio de la procuración Judicial. Artículos 250, 251 y 252. Reformados por Decreto 24 del 30 de enero de 1918.","decretos":["18","24"]},{"nota":70,"tipo":"REFORMA","texto":"Artículos 250, 251 y 252. Los Artículos 11 y 12 de la Ley Orgánica del Colegio de Abogados de Honduras decreto 18 del 28 de septiembre de 1965 publicado en el diario Oficial La Gaceta No. 18,686 del 8 de octubre de 1965, y el Reglamento para el ejercicio de la Procuración aprobado en Asamblea Ordinaria el 1 de enero de 1971, establecen los requisitos para el ejercicio de la procuración Judicial. Artículos 250, 251 y 252. Reformados por Decreto 24 del 30 de enero de 1918.","decretos":["18","24"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','251','378f03311a010f08481bf4fe4bbfe4bf1a477eaa29473812cc14815a35271152','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:252','mayalex_normativos','09_JUDICIAL','Sin embargo de lo dispuesto en los artículos anteriores, las partes podrán encomendar su representación en toda clase de juicios a cualquier ciudadano hondureño, mayor de edad, de notoria honradez que sepa leer y escribir, aunque no sea Procurador o Abogado, si no hubiere ninguna de estas dos clases en el término municipal; pero donde haya tres o más Abogados, los Procuradores necesitan firma y dirección de Abogado para poder litigar ante los Juzgados y Tribunales Superiores.','252','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":252,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"a3946a839dd86ad03717ce1dde937dbcfec48e2c6b3fb26e6cc7eb1f24923b6a","ubicacion":[],"constancias":[{"nota":69,"tipo":"REFORMA","texto":"Artículos 250, 251 y 252. Los Artículos 11 y 12 de la Ley Orgánica del Colegio de Abogados de Honduras decreto 18 del 28 de septiembre de 1965 publicado en el diario Oficial La Gaceta No. 18,686 del 8 de octubre de 1965, y el Reglamento para el ejercicio de la Procuración aprobado en Asamblea Ordinaria el 1 de enero de 1971, establecen los requisitos para el ejercicio de la procuración Judicial. Artículos 250, 251 y 252. Reformados por Decreto 24 del 30 de enero de 1918.","decretos":["18","24"]},{"nota":70,"tipo":"REFORMA","texto":"Artículos 250, 251 y 252. Los Artículos 11 y 12 de la Ley Orgánica del Colegio de Abogados de Honduras decreto 18 del 28 de septiembre de 1965 publicado en el diario Oficial La Gaceta No. 18,686 del 8 de octubre de 1965, y el Reglamento para el ejercicio de la Procuración aprobado en Asamblea Ordinaria el 1 de enero de 1971, establecen los requisitos para el ejercicio de la procuración Judicial. Artículos 250, 251 y 252. Reformados por Decreto 24 del 30 de enero de 1918.","decretos":["18","24"]},{"nota":71,"tipo":"REFERENCIA","texto":"Artículo 252. Con respecto a este Artículo deberá tenerse en consideración lo estipulado en la Ley de Colegiación Profesional Obligatoria, contenida en el Decreto No. 73 de 17 de mayo de 1962 publicada en el Diario Oficial La Gaceta No. 17,602 del 6 de junio de 1962. Colegio de Abogados de Honduras.","decretos":["73"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','252','a3946a839dd86ad03717ce1dde937dbcfec48e2c6b3fb26e6cc7eb1f24923b6a','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:253','mayalex_normativos','09_JUDICIAL','El Tribunal correspondiente en cuya jurisdicción residiere el Procurador, podrá suspenderla en su oficio por haber dejado de reunir las condiciones que exige esta ley. Tal suspensión deberá decretarse con audiencia del Procurador y con conocimiento de causa, de oficio o a petición de parte.','253','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":253,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8c30244c8caa11ec8c9c5176100765b8f9e534a9f2c2005f23b376e6aacd1812","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','253','8c30244c8caa11ec8c9c5176100765b8f9e534a9f2c2005f23b376e6aacd1812','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:254','mayalex_normativos','09_JUDICIAL','Sólo podrán ejercer la Procuración:

1. Los Abogados;

2. Los Doctores y Licenciados de la Facultad de Jurisprudencia y Ciencias Políticas.

3. Los Notarios.

4. Los que antes de la vigencia de las nuevas leyes hayan obtenido el Titulo de Bachiller en Derecho Civil.

5. Con firma de Abogado, en donde hubiere tres o más de ese título, los estudiantes del quinto y sexto curso de Facultad de Ciencias Jurídicas y Sociales: y por el término de dieciocho meses, contados desde la fecha del último examen ordinario de materias, los que habiendo aprobado el último curso de la misma Facultad, no hubieren obtenido su título de Licenciado. Uno u otro extremo se acreditarán con certificación del respectivo Decano.

6. Los parientes del poderdante dentro del cuarto grado de consanguinidad legítima o natural y segundo de afinidad legítima.

7. Los que conforme a esta ley, obtengan el título correspondiente.','254','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":254,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"9817d31c69bb301e4c85e33364ec5eb89db94fa21d15af71f552964a6a7cbf3a","ubicacion":[],"constancias":[{"nota":72,"tipo":"REFORMA","texto":"Reformado por el Decreto No.11 de fecha 18 de diciembre de 1951, publicado en el Diario Oficial La Gaceta número 14591 del 8 de enero de 1952, y vigente 10 días después de su promulgación; cuyo texto íntegro aparece al final, como anexo.","decretos":["11"]},{"nota":73,"tipo":"REFERENCIA","texto":"Conforme el Artículo 12, de la Ley Orgánica del Colegio de Abogados de Honduras, \"El ejercicio de la procuración corresponde exclusivamente a los Abogados y Licenciados en Ciencias Jurídicas y Sociales colegiados. Bajo la dirección de un Abogado colegiado, podrán ejercer la Procuración los Procuradores titulados y los estudiantes de los dos últimos años de la Facultad de Ciencias Jurídicas y Sociales, mediante autorización del Colegio, de conformidad con el Reglamento respectivo. En las mismas condiciones podrán ejercer la Procuración por el término de dieciocho meses, contados desde la fecha del último examen ordinario de materias, los estudiantes que habiendo aprobado el último curso de la Facultad de Ciencias Jurídicas y Sociales, no hubieren obtenido el título. Uno u otro extremo se acreditará con certificación extendida por la expresada Facultad.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (reforma integrada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','254','9817d31c69bb301e4c85e33364ec5eb89db94fa21d15af71f552964a6a7cbf3a','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:255','mayalex_normativos','09_JUDICIAL','Ningún Tribunal o Juez admitirá como Procurador a persona alguna en contravención a la presente ley. Por toda infracción de este precepto incurrirá cada Magistrado en una multa de treinta pesos, y será de veinte pesos para los Jueces de Letras o de primera instancia, y de diez pesos para los Jueces de Paz, y se reputarán nulos los actos en que hubiere intervenido el Procurador desautorizado. Estas multas se impondrán disciplinariamente por el Tribunal Superior.','255','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":255,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"255ceec914cea3c562d746ff857db2c710ee060628a35d87e7a290a823a73525","ubicacion":[],"constancias":[{"nota":74,"tipo":"REFERENCIA","texto":"La Unidad monetaria actual de Honduras es el Lempira, según Decreto Número 102 de fecha 3 de abril de 1926.","decretos":[]},{"nota":75,"tipo":"REFERENCIA","texto":"La Unidad monetaria actual de Honduras es el Lempira, según Decreto Número 102 de fecha 3 de abril de 1926.","decretos":[]},{"nota":76,"tipo":"REFERENCIA","texto":"La Unidad monetaria actual de Honduras es el Lempira, según Decreto Número 102 de fecha 3 de abril de 1926.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','255','255ceec914cea3c562d746ff857db2c710ee060628a35d87e7a290a823a73525','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:256','mayalex_normativos','09_JUDICIAL','El nombramiento de Procurador Judicial deberá hacerse por escritura pública, y por declaración escrita o por comparecencia verbal autorizadas por el Secretario del respectivo Juzgado o Tribunal.

En los juicios verbales podrán también hacerse este nombramiento por carta poder autorizada por Notario o Juez cartulario.','256','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":256,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"b34e88a4e459533b7d77c2d82e390c9a1e69aa370a0b5eabb15474904a9cd8ca","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','256','b34e88a4e459533b7d77c2d82e390c9a1e69aa370a0b5eabb15474904a9cd8ca','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:257','mayalex_normativos','09_JUDICIAL','Serán obligaciones de los Procuradores:

1. Presentar oportunamente el poder que tenga para comparecer en juicio, o devolverlo, si no lo aceptaren, tan pronto como sea posible, para que no sea perjudicado el poderdante, sin perjuicio de lo dispuesto en el Código Civil.

2. Seguir el juicio mientras no haya cesado en su encargo por alguna de las causas que se expresan en esta ley.

3. Transmitir al Abogado elegido por su cliente o por ellos mismos, todos los documentos, antecedentes e instrucciones que se les remitan, o que ellos mismos puedan adquirir, haciendo todo cuanto conduzca a la defensa de su poderdante, bajo la responsabilidad que las leyes imponen al mandatario.

Cuando no tuvieren instrucciones o fueren insuficientes las que se les hubiesen dado, hacer lo que requiera la naturaleza e índole del negocio.

4. Pagar los gastos que se causaren a su instancia.

5. Tener al cliente y al letrado siempre al corriente del curso del negocio que se les hubiere confiado.

6. Firmar todas las pretensiones que se presenten a nombre del cliente.

7. Oír y firmar los emplazamientos, citaciones y notificaciones de cualquier clase, inclusas las de sentencias, teniendo estas actuaciones la misma fuerza que si interviniere en ellas directamente el poderdante. No se admitirá la respuesta de que las expresadas diligencias se entienden con éste.

8. Asistir a todas las diligencias y actos que para los que las leyes lo prevengan.

9. Llevar un libro de conocimiento de negocios pendientes, y otro de cuentas con los litigantes, con los Abogados y con los auxiliares y subalternos que devenguen honorarios o derechos.

10. Dar a sus clientes cuentas documentadas de los gastos judiciales e inversión de las cantidades recibidas.','257','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":257,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"4860c00952194203e5f3c5b5a8ea9ff6aee23585747a5ad16385e8a5de1a6c2d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','257','4860c00952194203e5f3c5b5a8ea9ff6aee23585747a5ad16385e8a5de1a6c2d','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:258','mayalex_normativos','09_JUDICIAL','La aceptación del poder se entiende por hecha en el acto de presentarlo el Procurador, o de gestionar como tal en el juicio en que se le haya conferido.','258','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":258,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"675d172b5f769cc6b3ac319d8cf31d1ff47c83b506e072cabf7e6585b92392b6","ubicacion":[],"constancias":[{"nota":77,"tipo":"REFERENCIA","texto":"Artículo 258. Véase Código de Procedimientos Civiles, Artículo 7. La aceptación del poder se presume por el hecho de usar de él el Procurador. Aceptado el poder, queda el procurador obligado a cumplir los deberes que le impone la Ley de Organización y Atribuciones de los Tribunales, lo mismo que a recoger el Poder del Abogado que cese en la dirección del negocio las copias de los escritos y documentos y demás antecedentes que obren en su poder, para entregarlos al que se encargue de continuarlo.","decretos":[]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','258','675d172b5f769cc6b3ac319d8cf31d1ff47c83b506e072cabf7e6585b92392b6','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:259','mayalex_normativos','09_JUDICIAL','La representación en autos impone al representante la obligación de interponer todos los recursos que considere procedentes y que a su representado correspondan por la leyes.','259','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":259,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"3967f82325e6c802d4fa526fe0723868f18f86003f73c0d04de49467d00a0895","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','259','3967f82325e6c802d4fa526fe0723868f18f86003f73c0d04de49467d00a0895','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:260','mayalex_normativos','09_JUDICIAL','El Procurador responderá, pecuniaria o personalmente, de todo retraso o dilación que de él exclusivamente hubiere dependido, y de cualquier otra falta en el cumplimiento de sus obligaciones relativas a la tramitación del asunto y de las diligencias a que la falta o el retraso o dilación dieran lugar.

Será igualmente responsable a favor de su representado en los mismos casos en que el mandatario lo es a favor de su mandante, con arreglo a lo previsto en el Código Civil.','260','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":260,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"7b04fe8f5bcaaa79e38c89152c4409c2ec867e99408747407e9de59377630ed5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','260','7b04fe8f5bcaaa79e38c89152c4409c2ec867e99408747407e9de59377630ed5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:261','mayalex_normativos','09_JUDICIAL','Cesará el Procurador en su representación:

1. Por revocación del poder tan luego como conste en autos, ya sea expresa, ya tácitamente; por el nombramiento posterior de otro Procurador para el mismo negocio, o por gestión personal de la parte cuando no la hiciese sin perjuicio del poder conferido.

2. Por el desistimiento voluntario del Procurador, o por inhabilitarse éste para el ejercicio de la procuración, estando obligado a poner con anticipación uno y otro caso en conocimiento de sus poderdantes, judicialmente o por acta notarial. Mientras no aparezca en autos hecho el desistimiento, no podrá abandonar la representación que tuviere.

3. Por separarse el poderdante de la acción o de la oposición que hubiere formulado.

4. Por haber transmitido el mandante a otro sus derechos sobre la cosa litigiosa, cuando la transmisión haya sido reconocida por providencia o auto firme, con audiencia de la parte contraria.

5. Por haber terminado la personalidad del poderdante.

6. Por la terminación del acto, del pleito o de la causa para que se dio el poder.

7. Por muerte del Procurador.','261','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":261,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"8af159d1314a1e0ebda93ae52780be95ee83c4b1004bba06f0804f9a92b0b4e5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','261','8af159d1314a1e0ebda93ae52780be95ee83c4b1004bba06f0804f9a92b0b4e5','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:262','mayalex_normativos','09_JUDICIAL','Las disposiciones de este Título rigen respecto de los representantes legales y de los defensores en causas criminales, en cuanto les sean aplicables.','262','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":262,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"730f74503a3ab4e556cf819266a31b92992f4b16be4601632034459ad44af884","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','262','730f74503a3ab4e556cf819266a31b92992f4b16be4601632034459ad44af884','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:263','mayalex_normativos','09_JUDICIAL','Una ley especial establecerá al Arancel de Procuradores.','263','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":263,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"cdab9e980872939b47522c32d98e443660f3de7e966a353a7a54427ec884f396","ubicacion":[],"constancias":[{"nota":78,"tipo":"REFERENCIA","texto":"Artículo 263. El Artículo 2 inciso a) de la Ley Orgánica del Colegio de Abogados de Honduras, y decreto No. 82-96","decretos":["82-96"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','263','cdab9e980872939b47522c32d98e443660f3de7e966a353a7a54427ec884f396','OLA12_LOAT_2007_01',now()),
('OLA12_LOAT_2007_01:LEY_ORGANIZACION_TRIBUNALES:264','mayalex_normativos','09_JUDICIAL','La presente ley comenzará a regir el primero de marzo de 1906, quedando desde entonces derogada la Ley de Organización y Atribuciones de los Tribunales vigente.','264','Ley de Organización y Atribuciones de los Tribunales de Honduras (Decreto No. 76 de 1906)','{"norm_id":"HN:LEY_ORGANIZACION_TRIBUNALES","instrumento_id":"LEY_ORGANIZACION_TRIBUNALES","ingest_batch":"OLA12_LOAT_2007_01","ola":"OLA12","ordinal":264,"decreto":"76-1906","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE ORGANIZACIÓN Y ATRIBUCIONES DE LOS TRIBUNALES (ACTUALIZADA-07).pdf» (Acrobat PDFMaker 7.0, 10-dic-2007), con notas al pie y decretos de reforma anexos.","pdf_sha256":"77c0ad2ca8f77e76c3c6f941032aa47300d1c30ad9949c611a19ede2167d3c2a","article_sha256":"7b7f6f27fb21bde94f609d89d549032b465cc947b2a65ea3e5665d2991465a7a","ubicacion":["TITULO XVIII","DE LA OBSERVANCIA DE ESTA LEY"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_ORGANIZACION_TRIBUNALES','264','7b7f6f27fb21bde94f609d89d549032b465cc947b2a65ea3e5665d2991465a7a','OLA12_LOAT_2007_01',now())
